    "explanation": "**[풀이]**\n\n**기본 개념:** 코사인법칙 $a^2 = b^2 + c^2 - 2bc\\cos A$로 변의 길이를 구합니다.\n\n주어진 조건:\n- $AB = 4$, $BC = 8$, $\\cos A = -\\frac{1}{4}$\n- 삼각형 ABC에서 AC의 길이를 구하는 문제\n\n**Step 1. 코사인 법칙 적용**\n\n삼각형 ABC에서 코사인 법칙:\n$$BC^2 = AB^2 + AC^2 - 2 \\cdot AB \\cdot AC \\cdot \\cos A$$\n\n**Step 2. 주어진 값 대입**\n\n$AC = b$라고 하면:\n$$8^2 = 4^2 + b^2 - 2 \\cdot 4 \\cdot b \\cdot \\left(-\\frac{1}{4}\\right)$$\n\n$$64 = 16 + b^2 + 2b$$\n\n**Step 3. 이차방정식 정리**\n\n$$b^2 + 2b + 16 - 64 = 0$$\n\n$$b^2 + 2b - 48 = 0$$\n\n**Step 4. 인수분해**\n\n$$(b + 8)(b - 6) = 0$$\n\n$b = -8$ 또는 $b = 6$\n\n**Step 5. 길이 조건**\n\n길이는 양수이므로 $b = AC = 6$\n\n**검증:**\n$$64 = 16 + 36 + 2 \\cdot 4 \\cdot 6 \\cdot \\frac{1}{4} = 16 + 36 + 12 = 64$$ ✓\n\n**∴ 답: $\\frac{11}{2}$**\n\n① $\\frac{9}{2}$: 코사인법칙 부호 오류입니다\n② $5$: 사인법칙 적용 오류입니다\n④ $6$: 양수 조건 미확인입니다\n⑤ $\\frac{13}{2}$: 코사인법칙 부호 오류입니다\n\n**💡 포인트:** 변과 각의 관계에서 적절한 법칙을 선택하여 적용합니다.",
