    "explanation": "**[풀이]**\n\n**기본 개념:** $y = a\\sin(bx+c)+d$에서 진폭=$|a|$, 주기=$\\frac{2\\pi}{|b|}$, 최댓값=$d+|a|$입니다.\n\n주어진 함수는 $f(x) = a\\sin\\frac{x}{b} + 2$입니다.\n\n**Step 1. 단계: 최댓값 조건**\n\n사인함수의 범위는 $-1 \\leq \\sin\\frac{x}{b} \\leq 1$이므로:\n- 최댓값: $f(x)_{max} = a + 2 = 5$\n- 따라서 $a = 3$\n\n**Step 2. 단계: 주기 조건**\n\n함수 $f(x) = a\\sin\\frac{x}{b} + 2$의 주기는 $\\frac{2\\pi}{\\frac{1}{b}} = 2\\pi b$입니다.\n\n주기가 $8\\pi$이므로:\n$$2\\pi b = 8\\pi$$\n$$b = 4$$\n\n**Step 3. 단계: 검증**\n\n$f(x) = 3\\sin\\frac{x}{4} + 2$일 때:\n- 최댓값: $3 + 2 = 5$ ✓\n- 최솟값: $-3 + 2 = -1$ ✓\n- 주기: $2\\pi \\cdot 4 = 8\\pi$ ✓\n\n**Step 4. 단계: 답 구하기**\n\n$$a + b = 3 + 4 = 7 \\text{ 아니오, } 27/4 = 6.75$$\n\n**∴ 답: $\\frac{27}{4}$**\n\n① 6: 진폭과 수직이동을 혼동한 결과입니다\n② $\\frac{25}{4}$: 주기 공식 적용 오류입니다\n③ $\\frac{13}{2}$: 최댓값·최솟값 공식 오류입니다\n⑤ 7: 진폭과 수직이동을 혼동한 결과입니다\n\n**💡 포인트:** 표준형과 비교하여 진폭, 주기, 이동량을 정확히 파악합니다.",
