    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각함수 변환 공식 $\\cos(\\pi+\\theta)=-\\cos\\theta$, $\\sin(\\pi-\\theta)=\\sin\\theta$, $\\cos(\\frac{\\pi}{2}+\\theta)=-\\sin\\theta$를 이용하여 식을 변환한 뒤, 피타고라스 항등식과 사분면 조건으로 값을 구합니다.\n\n주어진 조건:\n- $\\sin(\\pi - \\theta) > 0$\n- $2\\cos\\theta = \\sin\\theta$\n\n**Step 1. 첫 번째 조건 분석**\n\n$\\sin(\\pi - \\theta) = \\sin\\theta$이므로\n\n$\\sin\\theta > 0$\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: $\\frac{\\sqrt{5}}{10}$**\n\n① $-\\frac{\\sqrt{5}}{5}$: 부호를 잘못 적용한 결과입니다\n② $-\\frac{\\sqrt{5}}{10}$: 항등식 대입 오류입니다\n③ $0$: 사분면 조건을 무시한 결과입니다\n⑤ $\\frac{\\sqrt{5}}{5}$: 부호를 잘못 적용한 결과입니다\n\n**참고:** 수능에서 이 유형은 빈출 문제이므로, 기본 공식을 정확히 암기하고 부호 결정 과정을 반복 연습하는 것이 중요합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
