    "explanation": "**[풀이]**\n\n**기본 개념:** $\\tan\\theta = \\frac{\\sin\\theta}{\\cos\\theta}$와 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 조건: $\\cos(\\theta - \\pi) = \\frac{3}{5}$이고 $\\tan\\theta < 0$일 때, $\\sin\\theta$의 값을 구하는 문제입니다.\n\n**Step 1. $\\cos(\\theta - \\pi)$ 정리**\n\n삼각함수의 덧셈공식을 이용하면:\n$$\\cos(\\theta - \\pi) = \\cos\\theta\\cos\\pi + \\sin\\theta\\sin\\pi$$\n$$= -\\cos\\theta + 0 = -\\cos\\theta$$\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: $-\\frac{4}{5}$ ② $-\\frac{3}{5}$ ③ $\\frac{1}{5}$ ④ $\\frac{3}{5}$ ⑤ $\\frac{4}{5}$**\n\n\n\n**참고:** 수능에서 이 유형은 빈출 문제이므로, 기본 공식을 정확히 암기하고 부호 결정 과정을 반복 연습하는 것이 중요합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
