    "explanation": "**[풀이]**\n\n**기본 개념:** $y = A\\sin(Bx+C)+D$에서 최댓값=$|A|+D$, 최솟값=$-|A|+D$입니다.\n\n주어진 함수: $f(x) = a\\cos bx + 3$ (단, $x \\in [0, 2\\pi]$)\n\n**Step 1. $x = \\frac{\\pi}{3}$에서의 조건**\n\n$x = \\frac{\\pi}{3}$에서 최댓값 13을 가지므로:\n$$f\\left(\\frac{\\pi}{3}\\right) = a\\cos\\left(\\frac{b\\pi}{3}\\right) + 3 = 13$$\n$$a\\cos\\left(\\frac{b\\pi}{3}\\right) = 10 \\cdots (1)$$\n\n**Step 2. 최댓값이 13이 되는 조건**\n\n$f(x)$의 최댓값이 13이므로:\n- $a > 0$인 경우: $a + 3 = 13$ → $a = 10$\n- $a < 0$인 경우: $-a + 3 = 13$ → $a = -10$\n\n**Step 3. 경우 1 ($a = 10$)**\n\n식 (1)에서:\n$$10\\cos\\left(\\frac{b\\pi}{3}\\right) = 10$$\n$$\\cos\\left(\\frac{b\\pi}{3}\\right) = 1$$\n$$\\frac{b\\pi}{3} = 2k\\pi \\text{ (단, } k \\text{는 정수)}$$\n$$b = 6k$$\n\n$[0, 2\\pi]$에서 $\\cos bx$가 완전한 주기를 가지려면 $b > 0$이므로 $b = 6$\n\n검증: $x = \\frac{\\pi}{3}$일 때, $f\\left(\\frac{\\pi}{3}\\right) = 10\\cos(2\\pi) + 3 = 10 + 3 = 13$ ✓\n\n**∴ 답: ③**\n\n① 12     ② 14     ③ 16     ④ 18     ⑤ 20: 진폭과 수직이동을 혼동한 결과입니다\n\n**💡 포인트:** 표준형과 비교하여 진폭, 주기, 이동량을 정확히 파악합니다.",
    "problem": "단한구간 $[0, 2\\pi]$에서 정의된 함수 $f(x) = a\\cos bx + 3$이\n\n$x = \\frac{\\pi}{3}$에서 최댓값 13을 갖도록 하는 두 자연수 $a, b$의\n\n순서쌍 $(a, b)$에 대하여 $a + b$의 최솟값은? [4점]\n\n① 12     ② 14     ③ 16     ④ 18     ⑤ 20",
