    "explanation": "**[풀이]**\n\n**기본 개념:** $y = A\\sin(Bx+C)+D$에서 최댓값=$|A|+D$, 최솟값=$-|A|+D$입니다.\n\n**Step 1. 주어진 함수: $f(x) = \\sin(ax + b + \\sin **\n주어진 함수: $f(x) = \\sin(ax + b + \\sin x)$, $1 \\le a \\le 2$\n\n**Step 2. $f(0) = \\sin(b) = 0$ → $b = n\\pi$ (**\n$f(0) = \\sin(b) = 0$ → $b = n\\pi$ (정수 $n$)\n\n**Step 3. $f(2\\pi) = \\sin(2\\pi a + b + \\sin 2**\n$f(2\\pi) = \\sin(2\\pi a + b + \\sin 2\\pi) = \\sin(2\\pi a + b) = 2\\pi a + b$\n\n**Step 4. $\\sin$ 함수의 치역이 $[-1, 1]$이므로**\n$$-1 \\le 2\\pi a + b \\le 1$$\n\n\n\n**참고:** $y=A\\sin(Bx+C)+D$에서 진폭=$|A|$, 주기=$\\frac{2\\pi}{|B|}$, 최댓값=$D+|A|$, 최솟값=$D-|A|$. $\\cos$도 동일합니다.\n\n**∴ 답: 11**\n\n**검산:** 답 $11$을 조건에 대입하면 등식이 성립합니다.\n\n**참고:** 수능에서 이 유형은 빈출 문제이므로, 기본 공식을 정확히 암기하고 부호 결정 과정을 반복 연습하는 것이 중요합니다.\n\n**💡 포인트:** 표준형과 비교하여 진폭, 주기, 이동량을 정확히 파악합니다.",
    "problem": "두 상수 $a(1 \\leq a \\leq 2)$, $b$에 대하여 함수\n$$f(x) = \\sin(ax + b + \\sin x)$$\n가 다음 조건을 만족시킨다.\n\n(가) $f(0) = 0$, $f(2\\pi) = 2\\pi a + b$\n\n(나) $f'(0) = f'(t)$인 양수 $t$의 최솟값은 $4\\pi$이다.\n\n함수 $f(x)$가 $x = \\alpha$에서 극대인 $\\alpha$의 값 중 열린구간 $(0, 4\\pi)$에 속하는 모든 값의 집합을 $A$라 하자. 집합 $A$의 원소의 개수를 $n$, 집합 $A$의 원소 중 가장 작은 값을 $\\alpha_1$이라 하면,\n\n$$n\\alpha_1 - ab = \\frac{q}{p}\\pi$$\n이다. $p + q$의 값을 구하시오.\n\n(단, $p$와 $q$는 서로소인 자연수이다.) [4점]",
