    "explanation": "**[풀이]**\n\n**기본 개념:** 사인법칙 $\\frac{a}{\\sin A} = 2R$에서 $R$은 외접원 반지름이며, 변의 길이를 직접 구할 수 있습니다.\n\n주어진 조건:\n- (가) $3\\sin A = 2\\sin B$\n- (나) $\\cos B = \\cos C$\n- 외접원의 넓이가 $9\\pi$일 때, 삼각형 ABC의 넓이를 구하는 문제\n\n**Step 1. 외접원의 반지름 구하기**\n\n외접원의 넓이가 $9\\pi$이므로:\n$$\\pi R^2 = 9\\pi$$\n$$R = 3$$\n\n**Step 2. 조건 (나)에서 각도 관계 파악**\n\n$\\cos B = \\cos C$이고 $0 < B, C < \\pi$이므로:\n$$B = C$$\n\n\n\n**참고:** 사인법칙 $\\frac{a}{\\sin A}=2R$, 코사인법칙 $c^2=a^2+b^2-2ab\\cos C$, 넓이 $S=\\frac{1}{2}ab\\sin C$를 상황에 맞게 선택합니다.\n\n**∴ 답: $\\frac{64}{9}\\sqrt{2}$**\n\n① $\\frac{32}{9}\\sqrt{2}$: 코사인법칙 부호 오류입니다\n② $\\frac{40}{9}\\sqrt{2}$: 사인법칙 적용 오류입니다\n③ $\\frac{16}{3}\\sqrt{2}$: 이차방정식 근 선택 오류입니다\n④ $\\frac{56}{9}\\sqrt{2}$: 양수 조건 미확인입니다\n\n**💡 포인트:** 변과 각의 관계에서 적절한 법칙을 선택하여 적용합니다.",
    "problem": "다음 조건을 만족시키는 삼각형 ABC의 외접원의 넓이가 $9\\pi$일 때, 삼각형 ABC의 넓이는? [4점]\n\n(가) $3\\sin A = 2\\sin B$\n(나) $\\cos B = \\cos C$\n\n① $\\frac{32}{9}\\sqrt{2}$\n\n② $\\frac{40}{9}\\sqrt{2}$\n\n③ $\\frac{16}{3}\\sqrt{2}$\n\n④ $\\frac{56}{9}\\sqrt{2}$\n\n⑤ $\\frac{64}{9}\\sqrt{2}$",
    "_reviewed": true,
