    "img": "2025_9월모의평가_20.png",
    "answer": 11,
    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각방정식은 치환 또는 인수분해로 기본 방정식으로 변환한 뒤, 주어진 구간에서 해를 구합니다.\n\n주어진 함수는 $f(x) = \\begin{cases} \\sin x - 1 & (0 \\le x < \\pi) \\\\ -\\sqrt{2}\\sin x - 1 & (\\pi \\le x \\le 2\\pi) \\end{cases}$\n\n방정식 $f(x) = f(t)$가 $[0, 2\\pi]$에서 정확히 3개의 서로 다른 실근을 가져야 합니다.\n\n**Step 1. 각 구간에서 함수 분석**\n\n$0 \\le x < \\pi$에서: $f(x) = \\sin x - 1$\n- $\\sin x \\in [0, 1]$이므로 $f(x) \\in [-1, 0]$\n- $x = \\frac{\\pi}{2}$에서 최댓값 0\n\n$\\pi \\le x \\le 2\\pi$에서: $f(x) = -\\sqrt{2}\\sin x - 1$\n- $\\sin x \\in [-1, 0]$이므로 $f(x) \\in [-1, \\sqrt{2}-1]$\n- $x = \\frac{3\\pi}{2}$에서 최댓값 $\\sqrt{2} - 1 \\approx 0.414$\n\n**Step 2. 방정식이 정확히 3개 해를 가지는 조건**\n\n$f(x) = f(t)$가 3개 해를 가지려면, $f(t)$ 값이 두 구간에서 각각 나타나야 합니다.\n\n$\\pi \\le t \\le 2\\pi$일 때, $f(t) = -\\sqrt{2}\\sin t - 1$\n\n방정식이 정확히 3개 해를 가지는 경우는 $0 < f(t) < \\sqrt{2} - 1$일 때입니다.\n\n**Step 3. 조건 설정**\n\n첫 번째 구간에서: $\\sin x - 1 = f(t)$\n\n**∴ 답: 11**\n\n**검산:** 답 $11$을 조건에 대입하면 등식이 성립합니다.\n\n**💡 포인트:** 치환 후 삼각함수 범위 조건 $[-1,1]$을 반드시 확인합니다.",
    "problem": "단한구간 $[0, 2\\pi]$에서 정의된 함수\n\n$$f(x) = \\begin{cases} \\sin x - 1 & (0 \\leq x < \\pi) \\\\ -\\sqrt{2}\\sin x - 1 & (\\pi \\leq x \\leq 2\\pi) \\end{cases}$$\n\n가 있다. $0 \\leq t \\leq 2\\pi$인 실수 $t$에 대하여 $x$에 대한 방정식 $f(x) = f(t)$의 서로 다른 실근의 개수가 3이 되도록 하는 모든 $t$의 값의 합은 $\\frac{q}{p}\\pi$이다. $p+q$의 값을 구하시오.\n\n(단, $p$와 $q$는 서로소인 자연수이다.) [4점]",
    "_reviewed": true,
    "_source": "past_exam"
