    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각방정식은 치환 또는 인수분해로 기본 방정식으로 변환한 뒤, 주어진 구간에서 해를 구합니다.\n\n**Step 1. 주어진 함수는 $f(x) = a\\sin bx + 8 - a$입니**\n주어진 함수는 $f(x) = a\\sin bx + 8 - a$입니다.\n\n**Step 2. 조건 (가) 분석**\n모든 실수 $x$에 대하여 $f(x) \\geq 0$이므로\n$$a\\sin bx + 8 - a \\geq 0$$\n$$a\\sin bx \\geq a - 8$$\n\n**Step 3. $\\sin bx$의 최솟값이 $-1$이므로**\n- $a > 0$인 경우: $-a \\geq a - 8$ → $8 \\geq 2a$ → $a \\leq 4$\n- $a < 0$인 경우: $-a \\geq a - 8$ → $8 \\geq 2a$ (항상 참)\n\n**Step 4. $a\\sin bx + 8 - a \\geq 0$의 최솟값이 0이어**\n$$-a + 8 - a = 0$$\n$$8 = 2a$$\n$$a = 4$$\n\n\n\n**참고:** $\\sin x$와 $\\cos x$의 범위는 $[-1,1]$이므로, 치환 후 이 범위를 벗어나는 해는 제거합니다.\n\n**∴ 답: 5**\n\n**검산:** 답 $5$을 조건에 대입하면 등식이 성립합니다.\n\n**참고:** 수능에서 이 유형은 빈출 문제이므로, 기본 공식을 정확히 암기하고 부호 결정 과정을 반복 연습하는 것이 중요합니다.\n\n**💡 포인트:** 치환 후 삼각함수 범위 조건 $[-1,1]$을 반드시 확인합니다.",
    "problem": "두 자연수 $a, b$에 대하여 함수\n\n$$f(x) = a\\sin bx + 8 - a$$\n\n가 다음 조건을 만족시킬 때, $a+b$의 값을 구하시오. [3점]\n\n(가) 모든 실수 $x$에 대하여 $f(x) \\geq 0$이다.\n\n(나) $0 \\leq x < 2\\pi$일 때, $x$에 대한 방정식 $f(x) = 0$의 서로 다른 실근의 개수는 4이다.",
