    "explanation": "**[풀이]**\n\n**기본 개념:** $\\tan\\theta = \\frac{\\sin\\theta}{\\cos\\theta}$와 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 조건:\n- $\\frac{3}{2}\\pi < \\theta < 2\\pi$ (제3, 4사분면)\n- $\\cos\\theta = \\frac{\\sqrt{6}}{3}$\n- $\\tan\\theta$의 값을 구하기\n\n**Step 1. $\\sin\\theta$ 구하기**\n\n$\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하면:\n\n$$\\sin^2\\theta = 1 - \\cos^2\\theta = 1 - \\frac{6}{9} = 1 - \\frac{2}{3} = \\frac{1}{3}$$\n\n$$\\sin\\theta = \\pm\\frac{1}{\\sqrt{3}} = \\pm\\frac{\\sqrt{3}}{3}$$\n\n**Step 2. $\\sin\\theta$의 부호 결정**\n\n주어진 범위 $\\frac{3}{2}\\pi < \\theta < 2\\pi$는 제4사분면입니다.\n\n제4사분면에서:\n- $\\cos\\theta > 0$ ✓ (주어진 $\\cos\\theta = \\frac{\\sqrt{6}}{3} > 0$)\n- $\\sin\\theta < 0$\n\n**∴ 답: $-\\sqrt{2}$**\n\n② $-\\frac{\\sqrt{2}}{2}$: 항등식 대입 오류입니다\n③ $0$: 사분면 조건을 무시한 결과입니다\n④ $\\frac{\\sqrt{2}}{2}$: 분자·분모를 혼동한 결과입니다\n⑤ $\\sqrt{2}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
