    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각부등식은 기본각을 기준으로 구간을 나누어 풉니다.\n\n주어진 부등식: $\\cos x \\leq \\sin \\frac{\\pi}{7}$, $0 \\leq x \\leq 2\\pi$\n\n**Step 1. 부등식 변형**\n\n$\\cos x \\leq \\sin \\frac{\\pi}{7}$를 정리하기 위해 삼각함수 항등식을 이용합니다.\n\n$\\sin \\frac{\\pi}{7} = \\cos\\left(\\frac{\\pi}{2} - \\frac{\\pi}{7}\\right) = \\cos\\frac{5\\pi}{14}$\n\n\n\n**참고:** $\\sin x$와 $\\cos x$의 범위는 $[-1,1]$이므로, 치환 후 이 범위를 벗어나는 해는 제거합니다.\n\n\n\n\n\n**보충 설명:** 삼각방정식을 풀 때는 $t = \\sin x$로 치환하여 대수방정식으로 변환합니다. 이때 $-1 \\le t \\le 1$ 범위를 반드시 확인하고, 주어진 구간에서 주기성을 이용하여 모든 해를 빠짐없이 구해야 합니다.\n\n**∴ 답: $\\frac{8}{7}\\pi$**\n\n② $\\frac{17}{14}\\pi$: 치환 과정 오류입니다\n③ $\\frac{9}{7}\\pi$: 해의 개수를 잘못 센 결과입니다\n④ $\\frac{19}{14}\\pi$: 주기성을 무시한 결과입니다\n⑤ $\\frac{10}{7}\\pi$: 범위 조건 미확인입니다\n\n\n\n**💡 포인트:** 치환 후 삼각함수 범위 조건 $[-1,1]$을 반드시 확인합니다.",
    "problem": "$0 \\leq x \\leq 2\\pi$일 때, 부등식\n\n$$\\cos x \\leq \\sin \\frac{\\pi}{7}$$\n\n를 만족시키는 모든 $x$의 값의 범위는 $\\alpha \\leq x \\leq \\beta$이다.\n\n$\\beta - \\alpha$의 값은? [4점]\n\n① $\\frac{8}{7}\\pi$\n\n② $\\frac{17}{14}\\pi$\n\n③ $\\frac{9}{7}\\pi$\n\n④ $\\frac{19}{14}\\pi$\n\n⑤ $\\frac{10}{7}\\pi$",
