    "answer": 3,
    "explanation": "**[풀이]**\n\n**기본 개념:** $y = A\\sin(Bx+C)+D$에서 최댓값=$|A|+D$, 최솟값=$-|A|+D$입니다.\n\n주어진 함수는 $f(x) = \\begin{cases} 2|\\sin 4x| & (x < 0) \\\\ -\\sin ax & (x \\geq 0) \\end{cases}$\n\n$g(x) = \\left|\\int_{-a\\pi}^{x} f(t)dt\\right|$이고, 가 실수 전체의 정의역에서 미분가능하려면 $g(x)$가 미분불가능한 점이 없어야 합니다.\n\n**Step 1. $x < 0$에서 적분 계산**\n\n$x < 0$일 때, $t \\in [-a\\pi, x]$에서:\n$$\\int_{-a\\pi}^{x} 2|\\sin 4t|dt$$\n\n$|\\sin 4t|$는 주기가 $\\frac{\\pi}{4}$인 함수입니다.\n\n**Step 2. $x \\geq 0$에서 적분 계산**\n\n$$\\int_{-a\\pi}^{x} f(t)dt = \\int_{-a\\pi}^{0} 2|\\sin 4t|dt + \\int_{0}^{x} (-\\sin at)dt$$\n\n$$= \\int_{-a\\pi}^{0} 2|\\sin 4t|dt + \\left[\\frac{\\cos at}{a}\\right]_0^x$$\n\n$$= \\int_{-a\\pi}^{0} 2|\\sin 4t|dt + \\frac{\\cos ax - 1}{a}$$\n\n**Step 3. $x = 0$에서의 조건**\n\n$g(x)$가 $x=0$에서 미분가능하려면, $\\int_{-a\\pi}^{0} 2|\\sin 4t|dt = 0$이어야 하고, $x=0$ 근처에서 적분값의 부호가 바뀌지 않아야 합니다.\n\n\n**∴ 답: $\\frac{5}{4}$**\n\n① $\\frac{1}{2}$: 진폭과 수직이동을 혼동한 결과입니다\n② $\\frac{3}{4}$: 주기 공식 적용 오류입니다\n③ $1$: 최댓값·최솟값 공식 오류입니다\n⑤ $\\frac{3}{2}$: 진폭과 수직이동을 혼동한 결과입니다\n\n**💡 포인트:** 표준형과 비교하여 진폭, 주기, 이동량을 정확히 파악합니다.",
    "problem": "실수 $a(0<a<2)$에 대하여 함수 $f(x)$를\n\n$$f(x) = \\begin{cases} 2|\\sin 4x| & (x<0) \\\\ -\\sin ax & (x \\geq 0) \\end{cases}$$\n\n이라 하자. 함수\n\n$$g(x) = \\left|\\int_{-a\\pi}^{x} f(t)dt\\right|$$\n\n가 실수 전체의 정의역에서 미분가능할 때, $a$의 최솟값은? [4점]\n\n① $\\frac{1}{2}$\n\n② $\\frac{3}{4}$\n\n③ $1$\n\n④ $\\frac{5}{4}$\n\n⑤ $\\frac{3}{2}$",
    "_reviewed": true,
    "_source": "past_exam"
