    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각함수 변환 공식 $\\cos(\\pi+\\theta)=-\\cos\\theta$, $\\sin(\\pi-\\theta)=\\sin\\theta$, $\\cos(\\frac{\\pi}{2}+\\theta)=-\\sin\\theta$를 이용하여 식을 변환한 뒤, 피타고라스 항등식과 사분면 조건으로 값을 구합니다.\n\n주어진 조건: $\\tan\\theta < 0$이고 $\\cos\\left(\\frac{\\pi}{2}+\\theta\\right) = \\frac{\\sqrt{5}}{5}$\n\n**Step 1. 삼각함수 항등식 적용**\n\n$\\cos\\left(\\frac{\\pi}{2}+\\theta\\right) = -\\sin\\theta = \\frac{\\sqrt{5}}{5}$\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: $-\\frac{2\\sqrt{5}}{5}$**\n\n② $-\\frac{\\sqrt{5}}{5}$: 항등식 대입 오류입니다\n③ $0$: 사분면 조건을 무시한 결과입니다\n④ $\\frac{\\sqrt{5}}{5}$: 분자·분모를 혼동한 결과입니다\n⑤ $\\frac{2\\sqrt{5}}{5}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$\\tan\\theta < 0$이고 $\\cos\\left(\\frac{\\pi}{2}+\\theta\\right)=\\frac{\\sqrt{5}}{5}$일 때, $\\cos\\theta$의 값은? [3점]\n\n① $-\\frac{2\\sqrt{5}}{5}$\n\n② $-\\frac{\\sqrt{5}}{5}$\n\n③ $0$\n\n④ $\\frac{\\sqrt{5}}{5}$\n\n⑤ $\\frac{2\\sqrt{5}}{5}$",
