    "explanation": "**[풀이]**\n\n**기본 개념:** 배각 공식 $\\sin 2\\theta = 2\\sin\\theta\\cos\\theta$, $\\cos 2\\theta = 1 - 2\\sin^2\\theta$를 이용합니다.\n\n주어진 함수: $f(x) = a - \\sqrt{3}\\tan 2x$\n\n구간 $\\left[-\\frac{\\pi}{6}, b\\right]$에서 최댓값 7, 최솟값 3을 가진다.\n\n**Step 1. 함수의 성질 파악**\n\n$\\tan 2x$는 증가함수이므로, $-\\sqrt{3}\\tan 2x$는 감소함수이다.\n\n\n\n**참고:** 배각 공식: $\\sin 2\\theta=2\\sin\\theta\\cos\\theta$, $\\cos 2\\theta=1-2\\sin^2\\theta=2\\cos^2\\theta-1$입니다.\n\n\n\n\n\n**보충 설명:** $\\cos 2\\theta$에는 세 가지 표현이 있습니다: $\\cos^2\\theta - \\sin^2\\theta$, $2\\cos^2\\theta - 1$, $1 - 2\\sin^2\\theta$. 주어진 조건에 따라 가장 효율적인 형태를 선택하는 것이 핵심입니다.\n\n**∴ 답: $\\frac{5\\pi}{12}$**\n\n① $\\frac{\\pi}{2}$: 배각 공식 적용 오류입니다\n③ $\\frac{\\pi}{3}$: 각도 변환 실수입니다\n④ $\\frac{\\pi}{4}$: 항등식 선택 오류입니다\n⑤ $\\frac{\\pi}{6}$: 배각 공식 적용 오류입니다\n\n\n\n**💡 포인트:** 배각 공식의 다양한 변형을 상황에 맞게 선택합니다.",
    "problem": "$f(x) = a - \\sqrt{3}\\tan 2x$\n\n가 단함수간 $\\left[-\\frac{\\pi}{6}, b\\right]$에서 최댓값 7, 최솟값 3을 가질 때,\n$a \\times b$의 값은? (단, $a, b$는 상수이다.) [4점]\n\n① $\\frac{\\pi}{2}$\n\n② $\\frac{5\\pi}{12}$\n\n③ $\\frac{\\pi}{3}$\n\n④ $\\frac{\\pi}{4}$\n\n⑤ $\\frac{\\pi}{6}$",
