    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 조건: $\\frac{\\pi}{2} < \\theta < \\pi$이고 $\\cos^2\\theta = \\frac{4}{9}$\n\n**Step 1. $\\cos\\theta$의 값 구하기**\n\n$\\cos^2\\theta = \\frac{4}{9}$이므로 $\\cos\\theta = \\pm\\frac{2}{3}$\n\n$\\frac{\\pi}{2} < \\theta < \\pi$ (2사분면)에서 $\\cos\\theta < 0$이므로:\n$$\\cos\\theta = -\\frac{2}{3}$$\n\n**Step 2. $\\sin^2\\theta$의 값 구하기**\n\n$\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하면:\n$$\\sin^2\\theta = 1 - \\cos^2\\theta = 1 - \\frac{4}{9} = \\frac{5}{9}$$\n\n$\\frac{\\pi}{2} < \\theta < \\pi$ (2사분면)에서 $\\sin\\theta > 0$이므로:\n$$\\sin\\theta = \\frac{\\sqrt{5}}{3}$$\n\n**Step 3. $\\sin^2\\theta + \\cos\\theta$ 계산**\n\n$$\\sin^2\\theta + \\cos\\theta = \\frac{5}{9} + \\left(-\\frac{2}{3}\\right)$$\n\n$$= \\frac{5}{9} - \\frac{6}{9} = -\\frac{1}{9}$$\n\n**∴ 답: $-\\frac{1}{9}$**\n\n① $-\\frac{4}{9}$: 부호를 잘못 적용한 결과입니다\n② $-\\frac{1}{3}$: 항등식 대입 오류입니다\n③ $-\\frac{2}{9}$: 사분면 조건을 무시한 결과입니다\n⑤ $0$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$\\frac{\\pi}{2} < \\theta < \\pi$일 때, $\\theta$에 대하여 $\\cos^2\\theta = \\frac{4}{9}$일 때, $\\sin^2\\theta + \\cos\\theta$의 값은? [3점]\n\n① $-\\frac{4}{9}$\n② $-\\frac{1}{3}$\n③ $-\\frac{2}{9}$\n④ $-\\frac{1}{9}$\n⑤ $0$",
