    "explanation": "**[풀이]**\n\n**기본 개념:** 배각 공식 $\\sin 2\\theta = 2\\sin\\theta\\cos\\theta$, $\\cos 2\\theta = 1 - 2\\sin^2\\theta$를 이용합니다.\n\n주어진 함수는 $f(x) = -\\sin 2x$이고, $x \\in [0, \\pi]$에서 정의됩니다.\n\n**Step 1. 극값 찾기**\n\n$f'(x) = -2\\cos 2x$\n\n극값은 $f'(x) = 0$일 때:\n$$-2\\cos 2x = 0$$\n$$\\cos 2x = 0$$\n$$2x = \\frac{\\pi}{2}, \\frac{3\\pi}{2}$$\n$$x = \\frac{\\pi}{4}, \\frac{3\\pi}{4}$$\n\n**Step 2. 극대값과 극소값 판정**\n\n$f''(x) = 4\\sin 2x$\n\n- $x = \\frac{\\pi}{4}$일 때: $f''(\\frac{\\pi}{4}) = 4\\sin\\frac{\\pi}{2} = 4 > 0$ → 극소값\n- $x = \\frac{3\\pi}{4}$일 때: $f''(\\frac{3\\pi}{4}) = 4\\sin\\frac{3\\pi}{2} = -4 < 0$ → 극대값\n\n**∴ 답: $\\frac{3}{\\pi}$**\n\n① $\\frac{1}{\\pi}$: 배각 공식 적용 오류입니다\n② $\\frac{2}{\\pi}$: 부호를 잘못 적용한 결과입니다\n④ $\\frac{4}{\\pi}$: 항등식 선택 오류입니다\n⑤ $\\frac{5}{\\pi}$: 배각 공식 적용 오류입니다\n\n**💡 포인트:** 배각 공식의 다양한 변형을 상황에 맞게 선택합니다.",
    "problem": "단항구간 $[0, \\pi]$에서 정의된 함수 $f(x) = -\\sin 2x$가 $x = a$에서 최댓값을 갖고 $x = b$에서 최솟값을 갖는다. 곡선 $y = f(x)$ 위의 두 점 $(a, f(a))$, $(b, f(b))$를 지나는 직선의 기울기는? [3점]\n\n① $\\frac{1}{\\pi}$\n\n② $\\frac{2}{\\pi}$\n\n③ $\\frac{3}{\\pi}$\n\n④ $\\frac{4}{\\pi}$\n\n⑤ $\\frac{5}{\\pi}$",
