    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각함수 변환 공식 $\\cos(\\pi+\\theta)=-\\cos\\theta$, $\\sin(\\pi-\\theta)=\\sin\\theta$, $\\cos(\\frac{\\pi}{2}+\\theta)=-\\sin\\theta$를 이용하여 식을 변환한 뒤, 피타고라스 항등식과 사분면 조건으로 값을 구합니다.\n\n주어진 조건:\n- $\\sin(\\pi - \\theta) = \\frac{5}{13}$\n- $\\cos\\theta < 0$\n\n**Step 1. $\\sin\\theta$ 구하기**\n\n삼각함수 공식 $\\sin(\\pi - \\theta) = \\sin\\theta$를 이용하면:\n$$\\sin\\theta = \\frac{5}{13}$$\n\n**Step 2. $\\cos\\theta$ 구하기**\n\n기본 삼각함수 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 사용:\n$$\\left(\\frac{5}{13}\\right)^2 + \\cos^2\\theta = 1$$\n$$\\frac{25}{169} + \\cos^2\\theta = 1$$\n$$\\cos^2\\theta = \\frac{144}{169}$$\n$$\\cos\\theta = \\pm\\frac{12}{13}$$\n\n주어진 조건 $\\cos\\theta < 0$이므로:\n$$\\cos\\theta = -\\frac{12}{13}$$\n\n**Step 3. $\\tan\\theta$ 구하기**\n\n$$\\tan\\theta = \\frac{\\sin\\theta}{\\cos\\theta} = \\frac{\\frac{5}{13}}{-\\frac{12}{13}} = \\frac{5}{13} \\times \\frac{-13}{12} = -\\frac{5}{12}$$\n\n**∴ 답: ②**\n\n① $-\\frac{12}{13}$ ② $-\\frac{5}{12}$ ③ $0$ ④ $\\frac{5}{12}$ ⑤ $\\frac{12}{13}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$\\sin(\\pi - \\theta) = \\frac{5}{13}$이고 $\\cos\\theta < 0$일 때, $\\tan\\theta$의 값은? [3점]\n\n① $-\\frac{12}{13}$ ② $-\\frac{5}{12}$ ③ $0$ ④ $\\frac{5}{12}$ ⑤ $\\frac{12}{13}$",
