    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 함수:\n- $f(x) = \\cos\\frac{\\pi x}{6}$\n- $g(x) = -3\\cos\\frac{\\pi x}{6} - 1$\n\n**Step 1. $y = f(x)$와 $y = k$의 교점**\n\n$\\cos\\frac{\\pi x}{6} = k$의 해를 $\\alpha_1, \\alpha_2$라 하면, $|\\alpha_1 - \\alpha_2| = 8$\n\n$[0, 12]$에서 $\\cos\\frac{\\pi x}{6}$의 주기는 $\\frac{2\\pi}{\\pi/6} = 12$\n\n코사인 함수가 같은 값을 갖는 두 점의 거리가 8이려면:\n- 한 주기가 12이므로, 대칭점 사이의 거리를 고려\n- $\\cos\\frac{\\pi x}{6} = k$에서 $\\frac{\\pi x_1}{6} = \\theta$, $\\frac{\\pi x_2}{6} = 2\\pi - \\theta$라 하면\n- $x_1 = \\frac{6\\theta}{\\pi}$, $x_2 = 12 - \\frac{6\\theta}{\\pi}$\n- $|x_1 - x_2| = |12 - \\frac{12\\theta}{\\pi}| = 8$\n\n**∴ 답: $\\frac{7}{2}$**\n\n① $3$: 부호를 잘못 적용한 결과입니다\n③ $4$: 사분면 조건을 무시한 결과입니다\n④ $\\frac{9}{2}$: 분자·분모를 혼동한 결과입니다\n⑤ $5$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "닫힌구간 $[0, 12]$에서 정의된 두 함수\n\n$$f(x) = \\cos\\frac{\\pi x}{6}, \\quad g(x) = -3\\cos\\frac{\\pi x}{6} - 1$$\n\n이 있다. 곡선 $y = f(x)$와 직선 $y = k$가 만나는 두 점의 $x$좌표를 $\\alpha_1, \\alpha_2$라 할 때, $|\\alpha_1 - \\alpha_2| = 8$이다. 곡선 $y = g(x)$와 직선 $y = k$가 만나는 두 점의 $x$좌표를 $\\beta_1, \\beta_2$라 할 때, $|\\beta_1 - \\beta_2|$의 값은? (단, $k$는 $-1 < k < 1$인 상수이다.) [4점]\n\n① $3$\n\n② $\\frac{7}{2}$\n\n③ $4$\n\n④ $\\frac{9}{2}$\n\n⑤ $5$",
