    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 함수는 $f(x) = \\begin{cases} x-4 & (x < a) \\\\ x+3 & (x \\geq a) \\end{cases}$\n\n$|f(x)|$가 실수 전체에서 연속이려면 $f(x)$가 연속이거나, $f(x)$가 불연속인 점에서 $f(x) = 0$이어야 합니다.\n\n**Step 1. $f(x)$의 연속성 확인**\n\n$x = a$에서 $f(x)$의 좌극한과 우극한:\n- 좌극한: $\\lim_{x \\to a^-} f(x) = a - 4$\n- 우극한: $\\lim_{x \\to a^+} f(x) = a + 3$\n\n$f(x)$가 $x=a$에서 연속이려면 $a - 4 = a + 3$이어야 하는데, 이는 불가능합니다.\n\nTherefore, $f(x)$는 $x=a$에서 불연속입니다.\n\n**Step 2. $|f(x)|$의 연속성 조건**\n\n$|f(x)|$가 $x=a$에서 연속이려면:\n$$\\lim_{x \\to a^-} |f(x)| = \\lim_{x \\to a^+} |f(x)| = |f(a)|$$\n\n$x = a$에서:\n- 좌극한: $\\lim_{x \\to a^-} |f(x)| = |a - 4|$\n- 우극한: $\\lim_{x \\to a^+} |f(x)| = |a + 3| = a + 3$ (왜냐하면 $a + 3 > 0$)\n- 함숫값: $f(a) = a + 3$이므로 $|f(a)| = a + 3$\n\n연속성을 위해: $|a - 4| = a + 3$\n\n**Step 3. 경우 분석**\n\n\n**∴ 답: $\\frac{1}{2}$**\n\n① $-1$: 부호를 잘못 적용한 결과입니다\n② $-\\frac{1}{2}$: 항등식 대입 오류입니다\n③ $0$: 사분면 조건을 무시한 결과입니다\n⑤ $1$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$$f(x) = \\begin{cases} x-4 & (x < a) \\\\ x+3 & (x \\geq a) \\end{cases}$$\n\n이 대하여 함수 $|f(x)|$가 실수 전체의 집합에서 연속일 때, 상수 $a$의 값은? [3점]\n\n① $-1$\n② $-\\frac{1}{2}$\n③ $0$\n④ $\\frac{1}{2}$\n⑤ $1$",
