    "explanation": "**[풀이]**\n\n**기본 개념:** $(\\sin\\theta \\pm \\cos\\theta)^2 = 1 \\pm 2\\sin\\theta\\cos\\theta$ 항등식을 이용합니다. 한 쪽이 주어지면 제곱하여 나머지를 구합니다.\n\n주어진 조건: $\\frac{\\pi}{2} < \\theta < \\pi$이고 $\\sin\\theta\\cos\\theta = -\\frac{12}{25}$\n\n**Step 1. $\\sin\\theta - \\cos\\theta$의 제곱 구하기**\n\n$(\\sin\\theta - \\cos\\theta)^2 = \\sin^2\\theta - 2\\sin\\theta\\cos\\theta + \\cos^2\\theta$\n\n$= 1 - 2\\sin\\theta\\cos\\theta$\n\n$= 1 - 2 \\times (-\\frac{12}{25})$\n\n$= 1 + \\frac{24}{25} = \\frac{49}{25}$\n\n**Step 2. $\\sin\\theta - \\cos\\theta$의 값 구하기**\n\n$(\\sin\\theta - \\cos\\theta)^2 = \\frac{49}{25}$이므로\n\n$\\sin\\theta - \\cos\\theta = \\pm\\frac{7}{5}$\n\n**Step 3. 부호 결정**\n\n주어진 범위 $\\frac{\\pi}{2} < \\theta < \\pi$에서:\n- $\\sin\\theta > 0$ (제2사분면)\n- $\\cos\\theta < 0$ (제2사분면)\n- $\\sin\\theta\\cos\\theta < 0$ ✓ (주어진 조건 만족)\n\n또한 $\\frac{\\pi}{2} < \\theta < \\pi$ 범위에서 일반적으로 $|\\sin\\theta| > |\\cos\\theta|$이므로\n\n\n**∴ 답: $\\frac{7}{5}$**\n\n① $\\frac{4}{5}$: 부호를 잘못 적용한 결과입니다\n② $1$: 항등식 대입 오류입니다\n③ $\\frac{6}{5}$: 사분면 조건을 무시한 결과입니다\n⑤ $\\frac{8}{5}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
