    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각함수 그래프에서 진폭($|A|$), 주기($\\frac{2\\pi}{|B|}$), 수직이동($D$)을 파악합니다.\n\n주어진 함수는 $y = 6\\sin\\frac{\\pi}{12}x$ (단, $0 \\le x \\le 12$)이고, 직선 $y = 3$과의 교점을 구하는 문제입니다.\n\n**Step 1. 교점의 조건**\n\n교점에서 다음이 성립합니다:\n$$6\\sin\\frac{\\pi}{12}x = 3$$\n\n**Step 2. 방정식 풀이**\n\n양변을 6으로 나누면:\n$$\\sin\\frac{\\pi}{12}x = \\frac{1}{2}$$\n\n$\\sin\\theta = \\frac{1}{2}$인 경우:\n$$\\theta = \\frac{\\pi}{6} + 2n\\pi \\text{ 또는 } \\theta = \\frac{5\\pi}{6} + 2n\\pi$$\n\n**Step 3. $x$ 값 구하기**\n\n$\\frac{\\pi}{12}x = \\frac{\\pi}{6}$인 경우:\n$$x = 2$$\n\n$\\frac{\\pi}{12}x = \\frac{5\\pi}{6}$인 경우:\n$$x = 10$$\n\n$0 \\le x \\le 12$ 범위에서 $x = 2 + 12n$ 또는 $x = 10 + 12n$ 형태이므로, 조건을 만족하는 값은 $x = 2$와 $x = 10$입니다.\n\n**Step 4. 두 교점 사이의 거리**\n\n점 A: $(2, 3)$, 점 B: $(10, 3)$\n\n두 점의 $y$좌표가 같으므로:\n$$AB = |10 - 2| = 8$$\n\n**∴ 답: 8**\n\n① 6: 진폭과 수직이동을 혼동한 결과입니다\n② 7: 주기 공식 적용 오류입니다\n④ 9: 위상이동을 무시한 결과입니다\n⑤ 10: 진폭과 수직이동을 혼동한 결과입니다\n\n**💡 포인트:** 표준형과 비교하여 진폭, 주기, 이동량을 정확히 파악합니다.",
    "problem": "함수 $y=6\\sin\\frac{\\pi}{12}x$ $(0 \\leq x \\leq 12)$의 그래프와 직선 $y=3$이 만나는 두 점을 각각 A, B라 할 때, 선분 AB의 길이는? [3점]\n\n① 6\n② 7\n③ 8\n④ 9\n⑤ 10",
