    "explanation": "**[풀이]**\n\n**기본 개념:** $(\\sin\\theta \\pm \\cos\\theta)^2 = 1 \\pm 2\\sin\\theta\\cos\\theta$ 항등식을 이용합니다. 한 쪽이 주어지면 제곱하여 나머지를 구합니다.\n\n주어진 조건: $\\pi < \\theta < \\frac{3}{2}\\pi$ (제3사분면), $\\tan\\theta = \\frac{12}{5}$\n\n**Step 1. 제3사분면에서 sin θ, cos θ의 부호 결정**\n\n제3사분면에서는 $\\sin\\theta < 0$, $\\cos\\theta < 0$\n\n**Step 2. tan θ로부터 sin θ, cos θ 구하기**\n\n$\\tan\\theta = \\frac{\\sin\\theta}{\\cos\\theta} = \\frac{12}{5}$\n\n$\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하면:\n\n$\\sin\\theta = -\\frac{12}{13}$, $\\cos\\theta = -\\frac{5}{13}$\n\n(제3사분면이므로 둘 다 음수)\n\n검증: $\\tan\\theta = \\frac{-\\frac{12}{13}}{-\\frac{5}{13}} = \\frac{12}{5}$ ✓\n\n**Step 3. sin θ + cos θ 계산**\n\n$$\\sin\\theta + \\cos\\theta = -\\frac{12}{13} + \\left(-\\frac{5}{13}\\right) = -\\frac{12}{13} - \\frac{5}{13} = -\\frac{17}{13}$$\n\n**∴ 답: $-\\frac{17}{13}$**\n\n② $-\\frac{7}{13}$: 항등식 대입 오류입니다\n③ $0$: 사분면 조건을 무시한 결과입니다\n④ $\\frac{7}{13}$: 분자·분모를 혼동한 결과입니다\n⑤ $\\frac{17}{13}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
