    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각방정식은 치환 또는 인수분해로 기본 방정식으로 변환한 뒤, 주어진 구간에서 해를 구합니다.\n\n**Step 1. 주어진 방정식: $\\left(\\sin\\frac{\\pi x}{2}**\n주어진 방정식: $\\left(\\sin\\frac{\\pi x}{2} - t\\right)\\left(\\cos\\frac{\\pi x}{2} - t\\right) = 0$\n\n**Step 2. 이 방정식의 해는 $\\sin\\frac{\\pi x}{2} = t$**\n이 방정식의 해는 $\\sin\\frac{\\pi x}{2} = t$ 또는 $\\cos\\frac{\\pi x}{2} = t$입니다.\n\n**Step 3. $0 \\le x < 4$ 범위에서**\n- $\\sin\\frac{\\pi x}{2}$는 $0$에서 $1$로 증가, $1$에서 $0$으로 감소\n- $\\cos\\frac{\\pi x}{2}$는 $1$에서 $0$으로 감소, $0$에서 $-1$로 감소\n\n**Step 4. $\\alpha(t)$: 가장 작은 근, $\\beta(t)$: 가**\n$\\alpha(t)$: 가장 작은 근, $\\beta(t)$: 가장 큰 근\n\n**∴ 답: ㄱ, ㄴ, ㄷ**\n\n① ㄱ: 범위 조건 미확인입니다\n② ㄱ, ㄴ: 치환 과정 오류입니다\n③ ㄱ, ㄷ: 해의 개수를 잘못 센 결과입니다\n④ ㄴ, ㄷ: 주기성을 무시한 결과입니다\n\n**💡 포인트:** 치환 후 삼각함수 범위 조건 $[-1,1]$을 반드시 확인합니다.",
    "problem": "$-1 \\leq t \\leq 1$인 실수 $t$에 대하여 $x$에 대한 방정식\n\n$$\\left(\\sin\\frac{\\pi x}{2} - t\\right)\\left(\\cos\\frac{\\pi x}{2} - t\\right) = 0$$\n\n의 실근 중에서 집합 $\\{x|0 \\leq x < 4\\}$에 속하는 가장 작은 값을 $\\alpha(t)$, 가장 큰 값을 $\\beta(t)$라 하자. $<$보기$>$에서 옳은 것만을 있는 대로 고른 것은? [4점]\n\n**< 보기 >**\n\nㄱ. $-1 \\leq t < 0$인 모든 실수 $t$에 대하여 $\\alpha(t) + \\beta(t) = 5$이다.\n\nㄴ. $\\{t|\\beta(t) - \\alpha(t) = \\beta(0) - \\alpha(0)\\} = \\left\\{t \\mid 0 \\leq t \\leq \\frac{\\sqrt{2}}{2}\\right\\}$\n\nㄷ. $\\alpha(t_1) = \\alpha(t_2)$인 두 실수 $t_1, t_2$에 대하여\n$$t_2 - t_1 = \\frac{1}{2} \\text{이면 } t_1 \\times t_2 = \\frac{1}{3} \\text{이다.}$$\n\n① ㄱ\n② ㄱ, ㄴ\n③ ㄱ, ㄷ\n④ ㄴ, ㄷ\n⑤ ㄱ, ㄴ, ㄷ",
