    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n**Step 1. 주어진 함수 $f(x) = 2x^3 + 3x^2 - 12x + **\n주어진 함수 $f(x) = 2x^3 + 3x^2 - 12x + 1$에서 극값을 구하기 위해 미분합니다.\n\n**Step 2. $f'(x) = 6x^2 + 6x - 12 = 6(x^2 + x**\n$f'(x) = 6x^2 + 6x - 12 = 6(x^2 + x - 2) = 6(x+2)(x-1)$\n\n**Step 3. 극값은 $f'(x) = 0$일 때이므로**\n$x = -2$ 또는 $x = 1$\n\n**Step 4. 부호 변화 분석**\n- $x < -2$: $f'(x) > 0$ (증가)\n- $-2 < x < 1$: $f'(x) < 0$ (감소)\n- $x > 1$: $f'(x) > 0$ (증가)\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: 15**\n\n① 13: 부호를 잘못 적용한 결과입니다\n② 14: 항등식 대입 오류입니다\n④ 16: 분자·분모를 혼동한 결과입니다\n⑤ 17: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "함수 $f(x) = 2x^3 + 3x^2 - 12x + 1$의 극댓값과 극솟값을 각각 $M, m$이라 할 때, $M + m$의 값은? [3점]\n\n① 13\n② 14\n③ 15\n④ 16\n⑤ 17",
