    "answer": 1,
    "explanation": "**[풀이]**\n\n**기본 개념:** $(\\sin\\theta \\pm \\cos\\theta)^2 = 1 \\pm 2\\sin\\theta\\cos\\theta$ 항등식을 이용합니다. 한 쪽이 주어지면 제곱하여 나머지를 구합니다.\n\n주어진 조건: $\\frac{\\pi}{2} < \\theta < \\pi$일 때, $\\frac{\\sin\\theta}{1-\\sin\\theta} - \\frac{\\sin\\theta}{1+\\sin\\theta} = 4$\n\n**Step 1. 좌변을 통분**\n\n$$\\frac{\\sin\\theta}{1-\\sin\\theta} - \\frac{\\sin\\theta}{1+\\sin\\theta} = \\frac{\\sin\\theta(1+\\sin\\theta) - \\sin\\theta(1-\\sin\\theta)}{(1-\\sin\\theta)(1+\\sin\\theta)}$$\n\n**Step 2. 분자 정리**\n\n$$= \\frac{\\sin\\theta + \\sin^2\\theta - \\sin\\theta + \\sin^2\\theta}{1-\\sin^2\\theta}$$\n\n$$= \\frac{2\\sin^2\\theta}{\\cos^2\\theta}$$\n\n**Step 3. 주어진 식에 대입**\n\n$$\\frac{2\\sin^2\\theta}{\\cos^2\\theta} = 4$$\n\n$$2\\sin^2\\theta = 4\\cos^2\\theta$$\n\n$$\\sin^2\\theta = 2\\cos^2\\theta$$\n\n**∴ 답: $-\\frac{1}{3}$**\n\n① $-\\frac{\\sqrt{3}}{3}$: 부호를 잘못 적용한 결과입니다\n③ $0$: 사분면 조건을 무시한 결과입니다\n④ $\\frac{1}{3}$: 분자·분모를 혼동한 결과입니다\n⑤ $\\frac{\\sqrt{3}}{3}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$\\frac{\\pi}{2} < \\theta < \\pi$인 $\\theta$에 대하여 $\\frac{\\sin\\theta}{1-\\sin\\theta} - \\frac{\\sin\\theta}{1+\\sin\\theta} = 4$일 때, $\\cos\\theta$의 값은? [3점]\n\n① $-\\frac{\\sqrt{3}}{3}$\n② $-\\frac{1}{3}$\n③ $0$\n④ $\\frac{1}{3}$\n⑤ $\\frac{\\sqrt{3}}{3}$",
