    "answer": 3,
    "explanation": "**[풀이]**\n\n**기본 개념:** $\\tan\\theta = \\frac{\\sin\\theta}{\\cos\\theta}$와 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 조건: $\\frac{\\pi}{2} < \\theta < \\pi$이고 $\\sin\\theta = \\frac{\\sqrt{21}}{7}$\n\n**Step 1. $\\cos\\theta$ 구하기**\n\n$\\sin^2\\theta + \\cos^2\\theta = 1$을 이용합니다.\n\n$$\\sin^2\\theta = \\left(\\frac{\\sqrt{21}}{7}\\right)^2 = \\frac{21}{49} = \\frac{3}{7}$$\n\n$$\\cos^2\\theta = 1 - \\frac{3}{7} = \\frac{4}{7}$$\n\n$$\\cos\\theta = \\pm\\frac{2}{\\sqrt{7}} = \\pm\\frac{2\\sqrt{7}}{7}$$\n\n**Step 2. $\\cos\\theta$의 부호 결정**\n\n$\\frac{\\pi}{2} < \\theta < \\pi$는 제2사분면이므로 $\\cos\\theta < 0$입니다.\n\n**∴ 답: ④**\n\n① $-\\frac{\\sqrt{3}}{2}$ ② $-\\frac{\\sqrt{3}}{4}$ ③ $0$ ④ $\\frac{\\sqrt{3}}{4}$ ⑤ $\\frac{\\sqrt{3}}{2}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$\\frac{\\pi}{2}<\\theta<\\pi$인 $\\theta$에 대하여 $\\sin\\theta=\\frac{\\sqrt{21}}{7}$일 때, $\\tan\\theta$의 값은?\n\n① $-\\frac{\\sqrt{3}}{2}$ ② $-\\frac{\\sqrt{3}}{4}$ ③ $0$ ④ $\\frac{\\sqrt{3}}{4}$ ⑤ $\\frac{\\sqrt{3}}{2}$",
