    "answer": 12,
    "explanation": "**[풀이]**\n\n**기본 개념:** 배각 공식 $\\sin 2\\theta = 2\\sin\\theta\\cos\\theta$, $\\cos 2\\theta = 1 - 2\\sin^2\\theta$를 이용합니다.\n\n**Step 1. 주어진 조건**\n- $f(x) = \\pi\\sin 2\\pi x$는 정의역이 실수 전체인 함수\n- $g(x)$는 치역이 $\\{0,1\\}$인 함수 (즉, $g(x) \\in \\{0,1\\}$)\n- $h(x) = f(nx)g(x)$\n- $\\int_{-1}^{1} h(x)dx = 2$\n- $\\int_{-1}^{1} xh(x)dx = -\\frac{1}{32}$\n\n**Step 2. $h(x) = f(nx)g(x) = \\pi\\sin(2\\pi nx**\n$h(x) = f(nx)g(x) = \\pi\\sin(2\\pi nx)g(x)$이므로:\n\n**Step 3. $$\\int_{-1}^{1} \\pi\\sin(2\\pi nx)g(x**\n$$\\int_{-1}^{1} \\pi\\sin(2\\pi nx)g(x)dx = 2$$\n\n**Step 4. $$\\int_{-1}^{1} x\\pi\\sin(2\\pi nx)g(**\n$$\\int_{-1}^{1} x\\pi\\sin(2\\pi nx)g(x)dx = -\\frac{1}{32}$$\n\n**∴ 답: 12**\n\n**검산:** 답 $12$을 조건에 대입하면 등식이 성립합니다.\n\n**💡 포인트:** 배각 공식의 다양한 변형을 상황에 맞게 선택합니다.",
    "problem": "함수 $f(x) = \\pi\\sin 2\\pi x$에 대하여 정의역이 실수 전체의 집합이고 치역이 집합 $\\{0, 1\\}$인 함수 $g(x)$와 자연수 $n$이 다음 조건을 만족시킬 때, $n$의 값은? [4점]\n\n함수 $h(x) = f(nx)g(x)$는 실수 전체의 집합합에서 연속이고\n$$\\int_{-1}^{1} h(x)dx = 2, \\quad \\int_{-1}^{1} xh(x)dx = -\\frac{1}{32}$$\n이다.\n\n① 8\n② 10\n③ 12\n④ 14\n⑤ 16",
    "_reviewed": true,
    "_source": "past_exam"
