    "img": "2021_수능가형_30.png",
    "answer": 5,
    "explanation": "**[풀이]**\n\n**기본 개념:** $y = A\\sin(Bx+C)+D$에서 최댓값=$|A|+D$, 최솟값=$-|A|+D$입니다.\n\n주어진 조건을 정리하면:\n- $f(x)$는 최고차항의 계수가 1인 삼차함수\n- $g(x) = f(\\sin^2 \\pi x)$\n- $0 < x < 1$에서 $g(x)$의 극댓값과 극솟값의 개수가 각각 3개\n- $g(x)$의 최댓값: $\\frac{1}{2}$, 최솟값: $0$\n\n**Step 1. 계산** $t = \\sin^2 \\pi x$로 치환하면, $0 < x < 1$일 때 $0 \\le t \\le 1$입니다.\n\n$g(x) = f(\\sin^2 \\pi x)$이므로:\n$$g'(x) = f'(\\sin^2 \\pi x) \\cdot 2\\sin \\pi x \\cos \\pi x \\cdot \\pi = \\pi f'(\\sin^2 \\pi x) \\sin 2\\pi x$$\n\n**Step 2. 계산** $0 < x < 1$에서 $g(x)$가 극값 3개를 가지려면, $f'(t) = 0$이 $0 < t < 1$에서 2개의 근을 가져야 합니다.\n\n$f'(t) = 0$의 근을 $\\alpha, \\beta$ ($0 < \\alpha < \\beta < 1$)라 하면:\n$$f'(t) = 3(t - \\alpha)(t - \\beta)$$\n\n**Step 3. 계산** 조건 (나)에서 $g(x)$의 최댓값이 $\\frac{1}{2}$, 최솟값이 $0$이므로:\n- $f(0) = 0$ (최솟값)\n- $f(\\alpha) = \\frac{1}{2}$ 또는 $f(\\beta) = \\frac{1}{2}$ (최댓값)\n\n\n**∴ 답: 5**\n\n**검산:** 답 $5$을 조건에 대입하면 등식이 성립합니다.\n\n**💡 포인트:** 표준형과 비교하여 진폭, 주기, 이동량을 정확히 파악합니다.",
    "problem": "최고차항의 계수가 1인 삼차함수 $f(x)$에 대하여 실수 전체의 집합에서 정의된 함수 $g(x) = f(\\sin^2 \\pi x)$가 다음 조건을 만족시킨다.\n\n(가) $0 < x < 1$에서 함수 $g(x)$가 극대가 되는 $x$의 개수가 3이고, 이때 극댓값이 모두 동일하다.\n\n(나) 함수 $g(x)$의 최댓값은 $\\frac{1}{2}$이고 최솟값은 0이다.\n\n$f(2) = a + b\\sqrt{2}$일 때, $a^2 + b^2$의 값을 구하시오. (단, $a$와 $b$는 유리수이다) [4점]",
