    "explanation": "**[풀이]**\n\n**기본 개념:** $y = A\\sin(Bx+C)+D$에서 최댓값=$|A|+D$, 최솟값=$-|A|+D$입니다.\n\n함수 $f(x) = 4\\cos x + 3$의 최댓값을 구하는 문제입니다.\n\n**Step 1. 코사인 함수의 범위**\n\n코사인 함수의 범위는 $-1 \\leq \\cos x \\leq 1$입니다.\n\n**Step 2. 함수의 최댓값 구하기**\n\n$f(x) = 4\\cos x + 3$의 최댓값은 $\\cos x$가 최대일 때 나타납니다.\n\n$\\cos x$의 최댓값이 $1$이므로:\n\n$$f(x)_{\\text{최댓값}} = 4 \\times 1 + 3 = 4 + 3 = 7$$\n\n\n\n**참고:** $y=A\\sin(Bx+C)+D$에서 진폭=$|A|$, 주기=$\\frac{2\\pi}{|B|}$, 최댓값=$D+|A|$, 최솟값=$D-|A|$. $\\cos$도 동일합니다.\n\n\n\n\n\n**보충 설명:** 삼각함수 $y = A\\sin(Bx+C)+D$에서 $A$는 진폭, $B$는 각진동수(주기 결정), $C$는 위상각, $D$는 수직이동입니다. 주기는 $\\frac{2\\pi}{|B|}$이며, 최댓값은 $D+|A|$, 최솟값은 $D-|A|$입니다. $B$가 클수록 주기가 짧아집니다.\n\n**∴ 답: 6**\n\n② 7: 주기 공식 적용 오류입니다\n③ 8: 최댓값·최솟값 공식 오류입니다\n④ 9: 위상이동을 무시한 결과입니다\n⑤ 10: 진폭과 수직이동을 혼동한 결과입니다\n\n\n\n**💡 포인트:** 표준형과 비교하여 진폭, 주기, 이동량을 정확히 파악합니다.",
    "problem": "함수 $f(x) = 4\\cos x + 3$의 최댓값은? [3점]\n\n① 6\n② 7\n③ 8\n④ 9\n⑤ 10",
