    "answer": 6,
    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각방정식은 치환 또는 인수분해로 기본 방정식으로 변환한 뒤, 주어진 구간에서 해를 구합니다.\n\n주어진 방정식: $4\\sin^2 x - 4\\cos\\left(\\frac{\\pi}{2}+x\\right) - 3 = 0$\n\n**Step 1. 삼각함수 항등식 적용**\n\n$\\cos\\left(\\frac{\\pi}{2}+x\\right) = -\\sin x$ 이므로:\n\n$$4\\sin^2 x - 4(-\\sin x) - 3 = 0$$\n$$4\\sin^2 x + 4\\sin x - 3 = 0$$\n\n**Step 2. 이차방정식 풀이**\n\n$t = \\sin x$로 치환하면:\n$$4t^2 + 4t - 3 = 0$$\n\n근의 공식을 사용하면:\n$$t = \\frac{-4 \\pm \\sqrt{16 + 48}}{8} = \\frac{-4 \\pm \\sqrt{64}}{8} = \\frac{-4 \\pm 8}{8}$$\n\n\n\n**참고:** $\\sin x$와 $\\cos x$의 범위는 $[-1,1]$이므로, 치환 후 이 범위를 벗어나는 해는 제거합니다.\n\n\n\n\n\n**보충 설명:** 삼각방정식을 풀 때는 $t = \\sin x$로 치환하여 대수방정식으로 변환합니다. 이때 $-1 \\le t \\le 1$ 범위를 반드시 확인하고, 주어진 구간에서 주기성을 이용하여 모든 해를 빠짐없이 구해야 합니다.\n\n**∴ 답: 6**\n\n**검산:** 답 $6$을 조건에 대입하면 등식이 성립합니다.\n\n\n\n**💡 포인트:** 치환 후 삼각함수 범위 조건 $[-1,1]$을 반드시 확인합니다.",
    "problem": "$0 \\le x < 4\\pi$일 때, 방정식\n\n$$4\\sin^2 x - 4\\cos\\left(\\frac{\\pi}{2}+x\\right)-3=0$$\n\n의 모든 해의 합은? [4점]\n\n① $5\\pi$ ② $6\\pi$ ③ $7\\pi$ ④ $8\\pi$ ⑤ $9\\pi$",
