    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 식: $(e^{2x}-1)^2 f(x) = a - 4\\cos\\frac{\\pi}{2}x$\n\n**Step 1. $x=0$일 때의 조건**\n\n$x=0$을 대입하면:\n$(e^0-1)^2 f(0) = a - 4\\cos 0$\n$(1-1)^2 f(0) = a - 4$\n$0 = a - 4$\n$a = 4$\n\n**Step 2. $f(x)$ 구하기**\n\n$a=4$이므로:\n$(e^{2x}-1)^2 f(x) = 4 - 4\\cos\\frac{\\pi}{2}x$\n\n$f(x) = \\frac{4 - 4\\cos\\frac{\\pi}{2}x}{(e^{2x}-1)^2}$\n\n$x \\to 0$일 때 $f(0)$을 구하기 위해 로피탈의 정리를 사용합니다.\n\n분자: $4 - 4\\cos\\frac{\\pi}{2}x$는 $x=0$에서 $4-4=0$\n\n분모: $(e^{2x}-1)^2$은 $x=0$에서 $0$\n\n**Step 3. 로피탈의 정리 적용**\n\n분자의 도함수: $4\\sin\\frac{\\pi}{2}x \\cdot \\frac{\\pi}{2} = 2\\pi\\sin\\frac{\\pi}{2}x$\n\n분모의 도함수: $2(e^{2x}-1) \\cdot 2e^{2x} = 4e^{2x}(e^{2x}-1)$\n\n여전히 $x=0$에서 $\\frac{0}{0}$이므로 다시 로피탈:\n\n분자의 2차 도함수: $2\\pi \\cdot \\cos\\frac{\\pi}{2}x \\cdot \\frac{\\pi}{2} = \\pi^2\\cos\\frac{\\pi}{2}x$\n\n\n**∴ 답: $\\frac{\\pi^2}{3}$**\n\n① $\\frac{\\pi^2}{6}$: 부호를 잘못 적용한 결과입니다\n② $\\frac{\\pi^2}{5}$: 항등식 대입 오류입니다\n③ $\\frac{\\pi^2}{4}$: 사분면 조건을 무시한 결과입니다\n⑤ $\\frac{\\pi^2}{2}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "실수 전체의 집합에서 연속인 함수 $f(x)$가 모든 실수 $x$에 대하여\n\n$$(e^{2x}-1)^2 f(x) = a - 4\\cos\\frac{\\pi}{2}x$$\n\n를 만족할 때, $a \\times f(0)$의 값은? (단, $a$는 상수이다.) [3점]\n\n① $\\frac{\\pi^2}{6}$\n\n② $\\frac{\\pi^2}{5}$\n\n③ $\\frac{\\pi^2}{4}$\n\n④ $\\frac{\\pi^2}{3}$\n\n⑤ $\\frac{\\pi^2}{2}$",
