    "explanation": "**[풀이]**\n\n**기본 개념:** $y = A\\sin(Bx+C)+D$에서 최댓값=$|A|+D$, 최솟값=$-|A|+D$입니다.\n\n**Step 1. 주어진 방정식: $x^2 - (2\\sin\\theta)x - 3\\**\n주어진 방정식: $x^2 - (2\\sin\\theta)x - 3\\cos^2\\theta - 5\\sin\\theta + 5 = 0$\n\n**Step 2. 이것을 $x$에 대한 이차방정식으로 보고 근의 공식을 적용하면**\n$$x = \\frac{2\\sin\\theta \\pm \\sqrt{4\\sin^2\\theta + 4(3\\cos^2\\theta + 5\\sin\\theta - 5)}}{2}$$\n\n**Step 3. 판별식을 정리하면**\n$$D = 4\\sin^2\\theta + 12\\cos^2\\theta + 20\\sin\\theta - 20$$\n$$= 4\\sin^2\\theta + 12(1-\\sin^2\\theta) + 20\\sin\\theta - 20$$\n$$= 4\\sin^2\\theta + 12 - 12\\sin^2\\theta + 20\\sin\\theta - 20$$\n$$= -8\\sin^2\\theta + 20\\sin\\theta - 8$$\n$$= -4(2\\sin^2\\theta - 5\\sin\\theta + 2)$$\n$$= -4(2\\sin\\theta - 1)(\\sin\\theta - 2)$$\n\n**Step 4. $\\sin\\theta \\leq 1$이므로 $(\\sin\\theta**\n$\\sin\\theta \\leq 1$이므로 $(\\sin\\theta - 2) < 0$\n\n**∴ 답: $4\\pi$**\n\n① $3\\pi$: 진폭과 수직이동을 혼동한 결과입니다\n③ $5\\pi$: 최댓값·최솟값 공식 오류입니다\n④ $6\\pi$: 위상이동을 무시한 결과입니다\n⑤ $7\\pi$: 진폭과 수직이동을 혼동한 결과입니다\n\n**💡 포인트:** 표준형과 비교하여 진폭, 주기, 이동량을 정확히 파악합니다.",
    "problem": "$0 \\leq \\theta < 2\\pi$일 때, $x$에 대한 이차방정식식\n\n$$x^2 - (2\\sin\\theta)x - 3\\cos^2\\theta - 5\\sin\\theta + 5 = 0$$\n\n이 실근을 갖도록 하는 $\\theta$의 최솟값과 최댓값을 각각 $\\alpha, \\beta$라 하자. $4\\beta - 2\\alpha$의 값은? [4점]\n\n① $3\\pi$\n\n② $4\\pi$\n\n③ $5\\pi$\n\n④ $6\\pi$\n\n⑤ $7\\pi$",
