    "explanation": "**[풀이]**\n\n**기본 개념:** 사인법칙 $\\frac{a}{\\sin A} = 2R$에서 $R$은 외접원 반지름이며, 변의 길이를 직접 구할 수 있습니다.\n\n주어진 조건:\n- 삼각형 ABC에서 반지름의 길이가 15인 원에 내접\n- $\\sin B = \\frac{7}{10}$\n- AC의 길이를 구하기\n\n**Step 1. 정현법칙 적용**\n\n원에 내접하는 삼각형에서 정현법칙:\n$$\\frac{AC}{\\sin B} = 2R$$\n\n여기서 $R = 15$ (외접원의 반지름)\n\n**Step 2. AC 계산**\n\n$$AC = 2R \\sin B$$\n\n$$AC = 2 \\times 15 \\times \\frac{7}{10}$$\n\n$$AC = 30 \\times \\frac{7}{10}$$\n\n$$AC = \\frac{210}{10}$$\n\n$$AC = 21$$\n\n\n\n**참고:** 사인법칙 $\\frac{a}{\\sin A}=2R$, 코사인법칙 $c^2=a^2+b^2-2ab\\cos C$, 넓이 $S=\\frac{1}{2}ab\\sin C$를 상황에 맞게 선택합니다.\n\n\n\n\n\n**보충 설명:** 사인법칙은 변과 대각의 비가 일정함을 나타냅니다. 외접원 반지름 $R$이 주어지면 $a = 2R\\sin A$로 변을 직접 구할 수 있습니다. 코사인법칙은 피타고라스 정리의 일반화입니다.\n\n**∴ 답: ③**\n\n**검산:** 구한 값을 원래 조건에 대입하여 등식이 성립하는지 확인합니다.\n\n\n\n\n\n**💡 포인트:** 변과 각의 관계에서 적절한 법칙을 선택하여 적용합니다.",
    "problem": "반지름의 길이가 15인 원에 내접하는 삼각형 ABC에서 $\\sin B = \\frac{7}{10}$일 때, 선분 AC의 길이를 구하시오. [3점]",
