    "img": "2021_9월모의평가가형_20.png",
    "answer": 20,
    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각함수 변환 공식 $\\cos(\\pi+\\theta)=-\\cos\\theta$, $\\sin(\\pi-\\theta)=\\sin\\theta$, $\\cos(\\frac{\\pi}{2}+\\theta)=-\\sin\\theta$를 이용하여 식을 변환한 뒤, 피타고라스 항등식과 사분면 조건으로 값을 구합니다.\n\n주어진 함수는 $f(x) = \\sin(\\pi\\sqrt{x})$이고, $g(x) = \\int_0^x t f(x-t) dt$입니다.\n\n**Step 1. 적분 계산**\n\n$g(x) = \\int_0^x t \\sin(\\pi\\sqrt{x-t}) dt$\n\n치환: $u = x - t$, $du = -dt$, $t = x - u$\n\n$t = 0$일 때 $u = x$, $t = x$일 때 $u = 0$\n\n$$g(x) = \\int_x^0 (x-u)\\sin(\\pi\\sqrt{u})(-du) = \\int_0^x (x-u)\\sin(\\pi\\sqrt{u})du$$\n\n$$g(x) = x\\int_0^x \\sin(\\pi\\sqrt{u})du - \\int_0^x u\\sin(\\pi\\sqrt{u})du$$\n\n**Step 2. 부분적분을 이용한 $\\int_0^x \\sin(\\pi\\sqrt{u**\n\n$v = \\sqrt{u}$로 치환하면 $u = v^2$, $du = 2v dv$\n\n$$\\int_0^x \\sin(\\pi\\sqrt{u})du = \\int_0^{\\sqrt{x}} \\sin(\\pi v) \\cdot 2v dv$$\n\n부분적분: $= \\left[-\\frac{2v}{\\pi}\\cos(\\pi v)\\right]_0^{\\sqrt{x}} + \\int_0^{\\sqrt{x}} \\frac{2}{\\pi}\\cos(\\pi v)dv$\n\n$$= -\\frac{2\\sqrt{x}}{\\pi}\\cos(\\pi\\sqrt{x}) + \\frac{2}{\\pi^2}\\sin(\\pi\\sqrt{x})$$\n\n\n**∴ 답: 20**\n\n**검산:** 답 $20$을 조건에 대입하면 등식이 성립합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "함수 $f(x) = \\sin(\\pi\\sqrt{x})$에 대하여 함수\n\n$$g(x) = \\int_0^x tf(x-t)dt \\quad (x \\geq 0)$$\n\n이 $x = a$에서 극대인 모든 $a$를 작은 수부터 크기순으로 나열할 때, $n$번째 수를 $a_n$이라 하자.\n\n$k^2 < a_6 < (k+1)^2$인 자연수 $k$의 값은? [4점]\n\n① 11\n② 14\n③ 17\n④ 20\n⑤ 23",
    "_reviewed": true,
    "_source": "past_exam"
