    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n**Step 1. 주어진 조건: 임의의 실수 $a$에 대하여 $\\{x|f(x)=a**\n주어진 조건: 임의의 실수 $a$에 대하여 $\\{x|f(x)=a\\} \\subset \\{x|g(x)=a\\}$\n\n**Step 2. 이는 $f(x) = a$의 모든 해가 $g(x) = a$의 해이**\n이는 $f(x) = a$의 모든 해가 $g(x) = a$의 해이기도 하다는 의미입니다.\n\n**Step 3. 함수의 치역 분석**\n- $f(x) = \\sin kx + 2$의 치역: $[2-1, 2+1] = [1, 3]$\n- $g(x) = 3\\cos 12x$의 치역: $[-3, 3]$\n\n**Step 4. 조건의 의미**\n임의의 $a$에 대해 $f(x) = a$이면 $g(x) = a$이어야 합니다.\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: 4**\n\n**검산:** 답 $4$을 조건에 대입하면 등식이 성립합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "단항구간 $[-2\\pi, 2\\pi]$에서 정의된 두 함수\n\n$f(x) = \\sin kx + 2$, $g(x) = 3\\cos 12x$\n\n에 대하여 다음 조건을 만족시키는 자연수 $k$의 개수는? [4점]\n\n실수 $a$가 두 곡선 $y=f(x)$, $y=g(x)$의 교점의 $y$좌표이면\n$$\\{x|f(x)=a\\} \\subset \\{x|g(x)=a\\}$$\n이다.\n\n① 3\n② 4\n③ 5\n④ 6\n⑤ 7",
    "_reviewed": true,
