    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 조건:\n- $\\overline{AB} = 8$\n- $\\angle A = 45°$\n- $\\angle B = 15°$\n- 삼각형 ABC에서 BC의 길이를 구하는 문제\n\n**Step 1. 각 C 구하기**\n\n삼각형의 내각의 합은 $180°$이므로:\n$$\\angle C = 180° - 45° - 15° = 120°$$\n\n**Step 2. 정현 법칙(Sine Rule) 적용**\n\n정현 법칙에 의해:\n$$\\frac{BC}{\\sin A} = \\frac{AB}{\\sin C}$$\n\n$$\\frac{BC}{\\sin 45°} = \\frac{8}{\\sin 120°}$$\n\n**Step 3. 삼각함수 값 대입**\n\n- $\\sin 45° = \\frac{\\sqrt{2}}{2}$\n- $\\sin 120° = \\sin(180° - 60°) = \\sin 60° = \\frac{\\sqrt{3}}{2}$\n\n$$\\frac{BC}{\\frac{\\sqrt{2}}{2}} = \\frac{8}{\\frac{\\sqrt{3}}{2}}$$\n\n**Step 4. BC 구하기**\n\n$$BC = \\frac{8 \\cdot \\frac{\\sqrt{2}}{2}}{\\frac{\\sqrt{3}}{2}}$$\n\n$$BC = \\frac{8\\sqrt{2}}{2} \\cdot \\frac{2}{\\sqrt{3}}$$\n\n$$BC = \\frac{8\\sqrt{2}}{\\sqrt{3}}$$\n\n$$BC = \\frac{8\\sqrt{2} \\cdot \\sqrt{3}}{3} = \\frac{8\\sqrt{6}}{3}$$\n\n**∴ 답: $\\frac{8\\sqrt{6}}{3}$**\n\n① $2\\sqrt{6}$: 부호를 잘못 적용한 결과입니다\n② $\\frac{7\\sqrt{6}}{3}$: 항등식 대입 오류입니다\n④ $3\\sqrt{6}$: 분자·분모를 혼동한 결과입니다\n⑤ $\\frac{10\\sqrt{6}}{3}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$\\overline{AB} = 8$이고 $\\angle A = 45°$, $\\angle B = 15°$인 삼각형 $ABC$에서 선분 $BC$의 길이는? [3점]\n\n① $2\\sqrt{6}$\n\n② $\\frac{7\\sqrt{6}}{3}$\n\n③ $\\frac{8\\sqrt{6}}{3}$\n\n④ $3\\sqrt{6}$\n\n⑤ $\\frac{10\\sqrt{6}}{3}$",
    "_reviewed": true,
