    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각부등식은 기본각을 기준으로 구간을 나누어 풉니다.\n\n**Step 1. 단계: 방정식 $4\\cos^2 x - 1 = 0$ 풀기**\n\n$4\\cos^2 x - 1 = 0$\n\n$\\cos^2 x = \\frac{1}{4}$\n\n$\\cos x = \\pm\\frac{1}{2}$\n\n$0 < x < 2\\pi$ 범위에서:\n- $\\cos x = \\frac{1}{2}$ ⟹ $x = \\frac{\\pi}{3}, \\frac{5\\pi}{3}$\n- $\\cos x = -\\frac{1}{2}$ ⟹ $x = \\frac{2\\pi}{3}, \\frac{4\\pi}{3}$\n\n**Step 2. 단계: 부등식 $\\sin x \\cos x < 0$ 분석**\n\n$\\sin x \\cos x < 0$은 $\\sin x$와 $\\cos x$의 부호가 반대일 때 성립합니다.\n\n- **제2사분면** ($\\frac{\\pi}{2} < x < \\pi$): $\\sin x > 0, \\cos x < 0$ ✓\n- **제4사분면** ($\\frac{3\\pi}{2} < x < 2\\pi$): $\\sin x < 0, \\cos x > 0$ ✓\n\n**∴ 답: $\\frac{8}{3}\\pi$**\n\n① $2\\pi$: 범위 조건 미확인입니다\n② $\\frac{7}{3}\\pi$: 치환 과정 오류입니다\n④ $3\\pi$: 주기성을 무시한 결과입니다\n⑤ $\\frac{10}{3}\\pi$: 범위 조건 미확인입니다\n\n**💡 포인트:** 치환 후 삼각함수 범위 조건 $[-1,1]$을 반드시 확인합니다.",
    "problem": "$0 < x < 2\\pi$일 때, 방정식 $4\\cos^2x - 1 = 0$과 부등식 $\\sin x \\cos x < 0$을 동시에 만족시키는 모든 $x$의 값의 합은? [3점]\n\n① $2\\pi$\n\n② $\\frac{7}{3}\\pi$\n\n③ $\\frac{8}{3}\\pi$\n\n④ $3\\pi$\n\n⑤ $\\frac{10}{3}\\pi$",
