    "explanation": "**[풀이]**\n\n**기본 개념:** $y = A\\sin(Bx+C)+D$에서 최댓값=$|A|+D$, 최솟값=$-|A|+D$입니다.\n\n**Step 1. 점 P의 속도를 구하기 위해 $x$와 $y$를 $t$에 대해 미**\n점 P의 속도를 구하기 위해 $x$와 $y$를 $t$에 대해 미분합니다.\n\n**Step 2. $\\frac{dx}{dt} = \\frac{d}{dt}(t + \\**\n$\\frac{dx}{dt} = \\frac{d}{dt}(t + \\sin t \\cos t) = 1 + \\cos t \\cos t + \\sin t (-\\sin t)$\n\n**Step 3. $= 1 + \\cos^2 t - \\sin^2 t = 1 + \\c**\n$= 1 + \\cos^2 t - \\sin^2 t = 1 + \\cos 2t$\n\n**Step 4. $\\frac{dy}{dt} = \\frac{d}{dt}(\\tan **\n$\\frac{dy}{dt} = \\frac{d}{dt}(\\tan t) = \\sec^2 t$\n\n\n\n**참고:** $y=A\\sin(Bx+C)+D$에서 진폭=$|A|$, 주기=$\\frac{2\\pi}{|B|}$, 최댓값=$D+|A|$, 최솟값=$D-|A|$. $\\cos$도 동일합니다.\n\n**∴ 답: $2$**\n\n① $1$: 진폭과 수직이동을 혼동한 결과입니다\n② $\\sqrt{3}$: 주기 공식 적용 오류입니다\n④ $2\\sqrt{2}$: 위상이동을 무시한 결과입니다\n⑤ $2\\sqrt{3}$: 진폭과 수직이동을 혼동한 결과입니다\n\n**💡 포인트:** 표준형과 비교하여 진폭, 주기, 이동량을 정확히 파악합니다.",
    "problem": "좌표평면 위를 움직이는 점 P의 시각 $t \\left(0 < t < \\frac{\\pi}{2}\\right)$에서의 위치 $(x, y)$가\n\n$$x = t + \\sin t \\cos t, \\quad y = \\tan t$$\n\n이다. $0 < t < \\frac{\\pi}{2}$에서 점 P의 속력의 최솟값은? [3점]\n\n① $1$\n\n② $\\sqrt{3}$\n\n③ $2$\n\n④ $2\\sqrt{2}$\n\n⑤ $2\\sqrt{3}$",
