    "explanation": "**[풀이]**\n\n**기본 개념:** 코사인법칙 $a^2 = b^2 + c^2 - 2bc\\cos A$로 변의 길이를 구합니다.\n\n주어진 조건:\n- 이등변삼각형 ABC에서 $\\overline{AB} = \\overline{AC}$\n- $\\angle A = \\alpha$, $\\angle B = \\beta$\n- $\\tan(\\alpha + \\beta) = -\\frac{3}{2}$\n\n**Step 1. 삼각형의 내각의 합 이용**\n\n이등변삼각형에서 $AB = AC$이므로 $\\angle B = \\angle C = \\beta$\n\n삼각형 내각의 합:\n$$\\alpha + \\beta + \\beta = 180°$$\n$$\\alpha + 2\\beta = 180°$$\n$$\\alpha + \\beta = 180° - \\beta$$\n\n**Step 2. $\\tan(\\alpha + \\beta)$ 값 이용**\n\n$$\\tan(\\alpha + \\beta) = \\tan(180° - \\beta) = -\\tan\\beta = -\\frac{3}{2}$$\n\n**∴ 답: $\\frac{21}{10}$**\n\n② $\\frac{11}{5}$: 사인법칙 적용 오류입니다\n③ $\\frac{23}{10}$: 이차방정식 근 선택 오류입니다\n④ $\\frac{12}{5}$: 양수 조건 미확인입니다\n⑤ $\\frac{5}{2}$: 코사인법칙 부호 오류입니다\n\n**💡 포인트:** 변과 각의 관계에서 적절한 법칙을 선택하여 적용합니다.",
    "problem": "$\\overline{AB} = \\overline{AC}$인 이등변삼각형 $ABC$에서 $\\angle A = \\alpha$, $\\angle B = \\beta$라 하자. $\\tan(\\alpha + \\beta) = -\\frac{3}{2}$일 때, $\\tan \\alpha$의 값은? [3점]\n\n① $\\frac{21}{10}$\n\n② $\\frac{11}{5}$\n\n③ $\\frac{23}{10}$\n\n④ $\\frac{12}{5}$\n\n⑤ $\\frac{5}{2}$",
