    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** 배각 공식 $\\sin 2\\theta = 2\\sin\\theta\\cos\\theta$, $\\cos 2\\theta = 1 - 2\\sin^2\\theta$를 이용합니다.\n\n곡선 $y = ax^2 - 2\\sin 2x$가 변곡점을 갖도록 하는 정수 $a$의 개수를 구하는 문제입니다.\n\n변곡점은 $y'' = 0$이고 $y''$의 부호가 바뀌는 점입니다.\n\n**Step 1. 단계: 도함수 구하기**\n\n$y' = 2ax - 4\\cos 2x$\n\n$y'' = 2a + 8\\sin 2x$\n\n**Step 2. 단계: 변곡점 조건**\n\n변곡점이 존재하려면 $y'' = 0$이 되는 점이 있어야 합니다.\n\n$2a + 8\\sin 2x = 0$\n\n$\\sin 2x = -\\frac{a}{4}$\n\n이 방정식이 해를 가지려면:\n$-1 \\leq -\\frac{a}{4} \\leq 1$\n\n$-4 \\leq -a \\leq 4$\n\n$-4 \\leq a \\leq 4$\n\n**Step 3. 단계: 변곡점에서 $y''$의 부호 변화 확인**\n\n$y'' = 2a + 8\\sin 2x$는 연속함수입니다.\n\n$\\sin 2x = -\\frac{a}{4}$인 점에서 $y'' = 0$입니다.\n\n$\\sin 2x$는 $-1$에서 $1$ 사이를 진동하므로, $-\\frac{a}{4}$를 지나면서 $\\sin 2x$의 값이 변합니다.\n\n**∴ 답: 6**\n\n① 4: 배각 공식 적용 오류입니다\n② 5: 부호를 잘못 적용한 결과입니다\n④ 7: 항등식 선택 오류입니다\n⑤ 8: 배각 공식 적용 오류입니다\n\n**💡 포인트:** 배각 공식의 다양한 변형을 상황에 맞게 선택합니다.",
    "problem": "곡선 $y=ax^2-2\\sin 2x$가 변곡점을 갖도록 하는 정수 $a$의 개수는? [3점]\n\n① 4\n② 5\n③ 6\n④ 7\n⑤ 8",
