    "answer": 3,
    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 함수: $f(x) = \\sin(x+\\alpha) + 2\\cos(x+\\alpha)$\n\n**Step 1. 도함수 구하기**\n$$f'(x) = \\cos(x+\\alpha) - 2\\sin(x+\\alpha)$$\n\n**Step 2. 주어진 조건 적용**\n$f'\\left(\\frac{\\pi}{4}\\right) = 0$이므로:\n$$\\cos\\left(\\frac{\\pi}{4}+\\alpha\\right) - 2\\sin\\left(\\frac{\\pi}{4}+\\alpha\\right) = 0$$\n\n$$\\cos\\left(\\frac{\\pi}{4}+\\alpha\\right) = 2\\sin\\left(\\frac{\\pi}{4}+\\alpha\\right)$$\n\n**Step 3. $\\tan\\alpha$ 구하기**\n양변을 $\\cos\\left(\\frac{\\pi}{4}+\\alpha\\right)$로 나누면:\n$$1 = 2\\tan\\left(\\frac{\\pi}{4}+\\alpha\\right)$$\n\n$$\\tan\\left(\\frac{\\pi}{4}+\\alpha\\right) = \\frac{1}{2}$$\n\n탄젠트 덧셈공식을 사용하면:\n$$\\tan\\left(\\frac{\\pi}{4}+\\alpha\\right) = \\frac{\\tan\\frac{\\pi}{4} + \\tan\\alpha}{1 - \\tan\\frac{\\pi}{4}\\tan\\alpha} = \\frac{1 + \\tan\\alpha}{1 - \\tan\\alpha}$$\n\n**∴ 답: $-\\frac{1}{3}$**\n\n① $-\\frac{5}{6}$: 부호를 잘못 적용한 결과입니다\n② $-\\frac{2}{3}$: 항등식 대입 오류입니다\n③ $-\\frac{1}{2}$: 사분면 조건을 무시한 결과입니다\n⑤ $-\\frac{1}{6}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "함수 $f(x) = \\sin(x+\\alpha) + 2\\cos(x+\\alpha)$에 대하여\n\n$f'\\left(\\frac{\\pi}{4}\\right) = 0$일 때, $\\tan\\alpha$의 값은? (단, $\\alpha$는 상수이다.) [3점]\n\n① $-\\frac{5}{6}$\n\n② $-\\frac{2}{3}$\n\n③ $-\\frac{1}{2}$\n\n④ $-\\frac{1}{3}$\n\n⑤ $-\\frac{1}{6}$",
    "_reviewed": true,
