    "answer": 4,
    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 조건:\n- $g(x) = \\frac{f(x)\\cos x}{e^x}$\n- $g'(\\pi) = e^\\pi g(\\pi)$\n- $f(\\pi) \\neq 0$\n\n**Step 1. $g'(x)$ 구하기**\n\n$g(x) = f(x)\\cos x \\cdot e^{-x}$이므로, 곱의 미분법을 적용합니다.\n\n$$g'(x) = [f(x)\\cos x]' \\cdot e^{-x} + f(x)\\cos x \\cdot (-e^{-x})$$\n\n$$= [f'(x)\\cos x - f(x)\\sin x]e^{-x} - f(x)\\cos x \\cdot e^{-x}$$\n\n$$= e^{-x}[f'(x)\\cos x - f(x)\\sin x - f(x)\\cos x]$$\n\n**Step 2. $g'(\\pi)$ 계산**\n\n$\\cos\\pi = -1$, $\\sin\\pi = 0$을 대입:\n\n$$g'(\\pi) = e^{-\\pi}[f'(\\pi)\\cdot(-1) - f(\\pi)\\cdot 0 - f(\\pi)\\cdot(-1)]$$\n\n$$= e^{-\\pi}[-f'(\\pi) + f(\\pi)]$$\n\n**Step 3. $g(\\pi)$ 계산**\n\n$$g(\\pi) = \\frac{f(\\pi)\\cos\\pi}{e^\\pi} = \\frac{f(\\pi)\\cdot(-1)}{e^\\pi} = -\\frac{f(\\pi)}{e^\\pi}$$\n\n**∴ 답: 4**\n\n**검산:** 답 $4$을 조건에 대입하면 등식이 성립합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "실수 전체의 정의역에서 미분가능한 함수 $f(x)$에 대하여 함수 $g(x)$를\n\n$$g(x) = \\frac{f(x)\\cos x}{e^x}$$\n\n라 하자. $g'(\\pi) = e^\\pi g(\\pi)$일 때, $\\frac{f'(\\pi)}{f(\\pi)}$의 값은? (단, $f(\\pi) \\neq 0$)\n\n① $e^{-2\\pi}$\n\n② $1$\n\n③ $e^{-\\pi}+1$\n\n④ $e^\\pi+1$\n\n⑤ $e^{2\\pi}$",
    "_reviewed": true,
    "_source": "past_exam"
