    "points": 3,
    "img": "2020_6월모의평가가형_23.png",
    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** $\\tan\\theta = \\frac{\\sin\\theta}{\\cos\\theta}$와 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 조건: $\\cos\\theta = \\frac{1}{7}$\n\n**Step 1. 기본 삼각함수값 구하기**\n\n$\\cos\\theta = \\frac{1}{7}$이므로\n\n$\\sin^2\\theta = 1 - \\cos^2\\theta = 1 - \\frac{1}{49} = \\frac{48}{49}$\n\n$\\sin\\theta = \\frac{4\\sqrt{3}}{7}$ (양수, 제1사분면 가정)\n\n**Step 2. $\\tan\\theta$ 구하기**\n\n$\\tan\\theta = \\frac{\\sin\\theta}{\\cos\\theta} = \\frac{\\frac{4\\sqrt{3}}{7}}{\\frac{1}{7}} = 4\\sqrt{3}$\n\n**Step 3. $\\csc\\theta$ 구하기**\n\n$\\csc\\theta = \\frac{1}{\\sin\\theta} = \\frac{1}{\\frac{4\\sqrt{3}}{7}} = \\frac{7}{4\\sqrt{3}} = \\frac{7\\sqrt{3}}{12}$\n\n**Step 4. $\\csc\\theta \\times \\tan\\theta$ 계산**\n\n$\\csc\\theta \\times \\tan\\theta = \\frac{7\\sqrt{3}}{12} \\times 4\\sqrt{3}$\n\n$= \\frac{7\\sqrt{3} \\times 4\\sqrt{3}}{12}$\n\n$= \\frac{28 \\times 3}{12}$\n\n$= \\frac{84}{12}$\n\n$= 7$\n\n**∴ 답: ③**\n\n**검산:** 구한 값을 원래 조건에 대입하여 등식이 성립하는지 확인합니다.\n\n\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$\\cos\\theta = \\frac{1}{7}$일 때, $\\csc\\theta \\times \\tan\\theta$의 값을 구하시오. [3점]",
    "_reviewed": true,
    "_source": "past_exam"
