    "answer": 5,
    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 곡선은 $C: y = \\sqrt{8-x^2}$ $(2 \\le x \\le 2\\sqrt{2})$이며, 이는 중심이 원점이고 반지름이 $2\\sqrt{2}$인 원의 일부입니다.\n\n**Step 1. 단계: 점 Q의 위치 결정**\n\n점 P는 곡선 C 위의 점이고, $OQ = 2$, $\\angle POQ = \\frac{\\pi}{4}$를 만족하는 점 Q를 찾습니다.\n\nP를 극좌표로 $(2\\sqrt{2}, \\theta)$로 나타내면, Q는 $(2, \\theta - \\frac{\\pi}{4})$입니다.\n\n**Step 2. 단계: 점들의 좌표 설정**\n\nP가 곡선 C 위에 있으므로 $P = (2\\sqrt{2}\\cos\\theta, 2\\sqrt{2}\\sin\\theta)$입니다.\n\n$Q = (2\\cos(\\theta - \\frac{\\pi}{4}), 2\\sin(\\theta - \\frac{\\pi}{4}))$\n\n$= (2 \\cdot \\frac{\\cos\\theta + \\sin\\theta}{\\sqrt{2}}, 2 \\cdot \\frac{\\sin\\theta - \\cos\\theta}{\\sqrt{2}})$\n\n$= (\\sqrt{2}(\\cos\\theta + \\sin\\theta), \\sqrt{2}(\\sin\\theta - \\cos\\theta))$\n\n**Step 3. 단계: 점 X와 Y 결정**\n\n- X: OP 방향의 단위벡터를 $\\vec{u}$라 하면, X는 OQ를 OP 방향으로 정사영한 점입니다.\n\n**∴ 답: 5**\n\n**검산:** 답 $5$을 조건에 대입하면 등식이 성립합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "곡선평면에서 곡선 $C: y = \\sqrt{8-x^2}$ ($2 \\le x \\le 2\\sqrt{2}$) 위의 점 $P$에 대하여 $OQ = 2$, $\\angle POQ = \\frac{\\pi}{4}$를 만족시키고 직선 $OP$의 아래부분에 있는 점을 $Q$라 하자.\n\n점 $P$가 곡선 $C$ 위를 움직일 때, 선분 $OP$ 위를 움직이는 점 $X$와 선분 $OQ$ 위를 움직이는 점 $Y$에 대하여\n\n$$\\overrightarrow{OZ} = \\overrightarrow{OP} + \\overrightarrow{OX} + \\overrightarrow{OY}$$\n\n를 만족시키는 점 $Z$가 나타내는 영역을 $D$라 하자.\n\n영역 $D$에 속하는 점 중에서 $y$축과의 거리가 최소인 점을 $R$라 할 때, 영역 $D$에 속하는 점 $Z$에 대하여\n\n$$\\overrightarrow{OR} \\cdot \\overrightarrow{OZ}$$의 최댓값과 최솟값의 합이 $a + b\\sqrt{2}$이다. $a + b$의 값을 구하시오. (단, $O$는 원점이고, $a$와 $b$는 유리수이다.) [4점]",
