    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 조건: $\\frac{\\pi}{2} < \\theta < \\pi$이고 $\\cos\\theta = -\\frac{3}{5}$\n\n**Step 1. $\\sin\\theta$ 구하기**\n\n$\\sin^2\\theta + \\cos^2\\theta = 1$에서\n\n$\\sin^2\\theta = 1 - \\cos^2\\theta = 1 - \\frac{9}{25} = \\frac{16}{25}$\n\n$\\frac{\\pi}{2} < \\theta < \\pi$ (제2사분면)이므로 $\\sin\\theta > 0$\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: $-\\frac{5}{3}$**\n\n① $-\\frac{5}{2}$: 부호를 잘못 적용한 결과입니다\n③ $-\\frac{5}{4}$: 사분면 조건을 무시한 결과입니다\n④ $\\frac{5}{4}$: 분자·분모를 혼동한 결과입니다\n⑤ $\\frac{5}{3}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$\\frac{\\pi}{2} < \\theta < \\pi$인 $\\theta$에 대하여 $\\cos\\theta = -\\frac{3}{5}$일 때, $\\csc(\\pi+\\theta)$의 값은? [3점]\n\n① $-\\frac{5}{2}$\n\n② $-\\frac{5}{3}$\n\n③ $-\\frac{5}{4}$\n\n④ $\\frac{5}{4}$\n\n⑤ $\\frac{5}{3}$",
