    "explanation": "**[풀이]**\n\n**기본 개념:** 배각 공식 $\\sin 2\\theta = 2\\sin\\theta\\cos\\theta$, $\\cos 2\\theta = 1 - 2\\sin^2\\theta$를 이용합니다.\n\n**Step 1. 주어진 정의역은 $-\\frac{\\pi}{4} < x < \\fra**\n주어진 정의역은 $-\\frac{\\pi}{4} < x < \\frac{\\pi}{4}$이고, $f(x) = \\tan 2x$입니다.\n\n**Step 2. $g(x)$는 $f(x)$의 역함수이므로**\n$$g(x) = \\arctan(x) \\text{ (단, } -\\infty < x < \\infty\\text{)}$$\n\n**Step 3. 더 정확히는, $f: (-\\frac{\\pi}{4}, \\frac{**\n$$g: \\mathbb{R} \\to (-\\frac{\\pi}{4}, \\frac{\\pi}{4})$$\n\n**Step 4. $y = \\tan 2x$이면 $x = g(y) = \\frac{1**\n$y = \\tan 2x$이면 $x = g(y) = \\frac{1}{2}\\arctan(y)$입니다.\n\n\n\n**참고:** 배각 공식: $\\sin 2\\theta=2\\sin\\theta\\cos\\theta$, $\\cos 2\\theta=1-2\\sin^2\\theta=2\\cos^2\\theta-1$입니다.\n\n**∴ 답: ③**\n\n**검산:** 구한 값을 원래 조건에 대입하여 등식이 성립하는지 확인합니다.\n\n\n\n**참고:** 수능에서 이 유형은 빈출 문제이므로, 기본 공식을 정확히 암기하고 부호 결정 과정을 반복 연습하는 것이 중요합니다.\n\n**💡 포인트:** 배각 공식의 다양한 변형을 상황에 맞게 선택합니다.",
