    "answer": 3,
    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각방정식은 치환 또는 인수분해로 기본 방정식으로 변환한 뒤, 주어진 구간에서 해를 구합니다.\n\n**Step 1. 주어진 이차방정식: $6x^2 + (4\\cos\\theta)x +**\n주어진 이차방정식: $6x^2 + (4\\cos\\theta)x + \\sin\\theta = 0$\n\n**Step 2. 이 방정식이 실근을 가져야 하므로 판별식 $D \\geq 0$**\n$$D = (4\\cos\\theta)^2 - 4 \\cdot 6 \\cdot \\sin\\theta \\geq 0$$\n$$16\\cos^2\\theta - 24\\sin\\theta \\geq 0$$\n$$16(1-\\sin^2\\theta) - 24\\sin\\theta \\geq 0$$\n$$16 - 16\\sin^2\\theta - 24\\sin\\theta \\geq 0$$\n$$16\\sin^2\\theta + 24\\sin\\theta - 16 \\leq 0$$\n$$2\\sin^2\\theta + 3\\sin\\theta - 2 \\leq 0$$\n$$(2\\sin\\theta - 1)(\\sin\\theta + 2) \\leq 0$$\n\n**Step 3. $\\sin\\theta + 2 > 0$ (항상 참)이므로**\n$$2\\sin\\theta - 1 \\leq 0$$\n$$\\sin\\theta \\leq \\frac{1}{2}$$\n\n**Step 4. $0 \\leq \\theta < 2\\pi$ 범위에서 $\\sin\\t**\n$$\\theta \\in [0, \\frac{\\pi}{6}] \\cup [\\frac{5\\pi}{6}, 2\\pi)$$\n\n**∴ 답: $\\dfrac{4}{3}\\pi$**\n\n① $\\dfrac{5}{6}\\pi$: 범위 조건 미확인입니다\n② $\\pi$: 치환 과정 오류입니다\n③ $\\dfrac{7}{6}\\pi$: 해의 개수를 잘못 센 결과입니다\n⑤ $\\dfrac{3}{2}\\pi$: 범위 조건 미확인입니다\n\n**💡 포인트:** 치환 후 삼각함수 범위 조건 $[-1,1]$을 반드시 확인합니다.",
    "problem": "$0 \\leq \\theta < 2\\pi$일 때, $x$에 대한 이차방정식\n$$6x^2 + (4\\cos\\theta)x + \\sin\\theta = 0$$\n이 실근을 갖지 않도록 하는 모든 $\\theta$의 값의 범위는 $\\alpha < \\theta < \\beta$이다. $3\\alpha + \\beta$의 값은? [3점]\n\n① $\\dfrac{5}{6}\\pi$\n\n② $\\pi$\n\n③ $\\dfrac{7}{6}\\pi$\n\n④ $\\dfrac{4}{3}\\pi$\n\n⑤ $\\dfrac{3}{2}\\pi$",
    "_reviewed": true,
    "_source": "past_exam"
