    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n**Step 1. 점 $\\left(-\\frac{\\pi}{2}, 0\\right)$에**\n점 $\\left(-\\frac{\\pi}{2}, 0\\right)$에서 곡선 $y = \\sin x$ $(x > 0)$에 그은 접선의 접점의 $x$좌표를 $a_n$이라 하자.\n\n**Step 2. 곡선 $y = \\sin x$ 위의 점 $(a, \\sin a)$에**\n$$y - \\sin a = \\cos a \\left(x - a\\right)$$\n\n**Step 3. 이 접선이 점 $\\left(-\\frac{\\pi}{2}, 0\\ri**\n$$0 - \\sin a = \\cos a \\left(-\\frac{\\pi}{2} - a\\right)$$\n$$-\\sin a = -\\cos a \\left(\\frac{\\pi}{2} + a\\right)$$\n$$\\sin a = \\cos a \\left(\\frac{\\pi}{2} + a\\right)$$\n$$\\tan a = \\frac{\\pi}{2} + a$$\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: 5**\n\n**검산:** 답 $5$을 조건에 대입하면 등식이 성립합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "점 $\\left(-\\frac{\\pi}{2}, 0\\right)$에서 곡선 $y=\\sin x$ $(x>0)$에 접선을 그어 접점의 $x$좌표를 작은 수부터 크기순으로 모두 나열할 때, $n$번째 수를 $a_n$이라 하자. 모든 자연수 $n$에 대하여 $\\langle$보기$\\rangle$에서 옳은 것만을 있는 대로 고른 것은? [4점]\n\n$\\langle$보 기$\\rangle$\n\nㄱ. $\\tan a_n = a_n + \\frac{\\pi}{2}$\n\nㄴ. $\\tan a_{n+2} - \\tan a_n > 2\\pi$\n\nㄷ. $a_{n+1} + a_{n+2} > a_n + a_{n+3}$\n\n① ㄱ\n② ㄱ, ㄴ\n③ ㄱ, ㄷ\n④ ㄴ, ㄷ\n⑤ ㄱ, ㄴ, ㄷ",
