    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 매개변수 방정식: $x = 1 - \\cos 4t$, $y = \\frac{1}{4}\\sin 4t$ (단, $t \\geq 0$)\n\n**Step 1. 점 P의 자취 구하기**\n\n$x = 1 - \\cos 4t$에서 $\\cos 4t = 1 - x$\n\n$y = \\frac{1}{4}\\sin 4t$에서 $\\sin 4t = 4y$\n\n삼각함수 항등식 $\\sin^2 4t + \\cos^2 4t = 1$을 이용하면:\n\n$(4y)^2 + (1-x)^2 = 1$\n\n$16y^2 + (1-x)^2 = 1$\n\n$(x-1)^2 + 16y^2 = 1$\n\n이는 중심이 $(1, 0)$이고, $x$축 방향 반지름이 $1$, $y$축 방향 반지름이 $\\frac{1}{4}$인 타원입니다.\n\n**Step 2. 속력 구하기**\n\n$\\frac{dx}{dt} = 4\\sin 4t$\n\n$\\frac{dy}{dt} = \\cos 4t$\n\n속력: $v = \\sqrt{\\left(\\frac{dx}{dt}\\right)^2 + \\left(\\frac{dy}{dt}\\right)^2} = \\sqrt{16\\sin^2 4t + \\cos^2 4t}$\n\n$= \\sqrt{16\\sin^2 4t + \\cos^2 4t}$\n\n$= \\sqrt{15\\sin^2 4t + \\sin^2 4t + \\cos^2 4t}$\n\n$= \\sqrt{15\\sin^2 4t + 1}$\n\n**Step 3. 속력의 최댓값 구하기**\n\n$\\sin^2 4t$의 최댓값은 $1$이므로:\n\n\n**∴ 답: ③**\n\n**검산:** 구한 값을 원래 조건에 대입하여 등식이 성립하는지 확인합니다.\n\n\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "좌표평면 위를 움직이는 점 P의 시각 $t(t \\geq 0)$에서의 위치 $(x, y)$가\n\n$$x = 1 - \\cos 4t, \\quad y = \\frac{1}{4}\\sin 4t$$\n\n이다. 점 P의 속력이 최대일 때, 점 P의 가속도의 크기를 구하시오. [3점]",
