    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각함수 변환 공식 $\\cos(\\pi+\\theta)=-\\cos\\theta$, $\\sin(\\pi-\\theta)=\\sin\\theta$, $\\cos(\\frac{\\pi}{2}+\\theta)=-\\sin\\theta$를 이용하여 식을 변환한 뒤, 피타고라스 항등식과 사분면 조건으로 값을 구합니다.\n\n주어진 적분을 계산합니다: $\\int_0^\\pi x\\cos(\\pi - x)dx$\n\n**Step 1. 삼각함수 항등식 적용**\n\n$\\cos(\\pi - x) = -\\cos x$ 이므로:\n\n$$\\int_0^\\pi x\\cos(\\pi - x)dx = \\int_0^\\pi x \\cdot (-\\cos x)dx = -\\int_0^\\pi x\\cos x dx$$\n\n**Step 2. 부분적분**\n\n$-\\int_0^\\pi x\\cos x dx$를 계산하기 위해 부분적분을 사용합니다.\n\n- $u = x$, $dv = \\cos x dx$\n- $du = dx$, $v = \\sin x$\n\n$$-\\int_0^\\pi x\\cos x dx = -\\left[x\\sin x\\Big|_0^\\pi - \\int_0^\\pi \\sin x dx\\right]$$\n\n**Step 3. 첫 번째 항 계산**\n\n$$x\\sin x\\Big|_0^\\pi = \\pi\\sin\\pi - 0\\cdot\\sin 0 = \\pi \\cdot 0 - 0 = 0$$\n\n**Step 4. 두 번째 항 계산**\n\n$$\\int_0^\\pi \\sin x dx = -\\cos x\\Big|_0^\\pi = -\\cos\\pi - (-\\cos 0) = -(-1) + 1 = 2$$\n\n**Step 5. 최종 계산**\n\n$$-\\left[0 - 2\\right] = -(-2) = 2$$\n\n**∴ 답: ②**\n\n\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$\\int_{0}^{\\pi} x \\cos(\\pi - x)dx$의 값을 구하시오. [3점]",
