    "explanation": "**[풀이]**\n\n**기본 개념:** 배각 공식 $\\sin 2\\theta = 2\\sin\\theta\\cos\\theta$, $\\cos 2\\theta = 1 - 2\\sin^2\\theta$를 이용합니다.\n\n곡선 $y = |\\sin 2x| + 1$과 두 직선 $x = \\frac{\\pi}{4}$, $x = \\frac{5\\pi}{4}$ 사이의 부분에서 둘러싼 넓이를 구합니다.\n\n**Step 1. 단계: $\\sin 2x$의 부호 결정**\n\n$x \\in [\\frac{\\pi}{4}, \\frac{5\\pi}{4}]$일 때, $2x \\in [\\frac{\\pi}{2}, \\frac{5\\pi}{2}]$\n\n- $x \\in [\\frac{\\pi}{4}, \\frac{3\\pi}{4}]$일 때: $2x \\in [\\frac{\\pi}{2}, \\frac{3\\pi}{2}]$ → $\\sin 2x \\geq 0$\n- $x \\in [\\frac{3\\pi}{4}, \\frac{5\\pi}{4}]$일 때: $2x \\in [\\frac{3\\pi}{2}, \\frac{5\\pi}{2}]$ → $\\sin 2x \\leq 0$\n\n**Step 2. 단계: 절댓값 풀기**\n\n$$y = |\\sin 2x| + 1 = \\begin{cases} \\sin 2x + 1 & \\frac{\\pi}{4} \\leq x \\leq \\frac{3\\pi}{4} \\\\ -\\sin 2x + 1 & \\frac{3\\pi}{4} \\leq x \\leq \\frac{5\\pi}{4} \\end{cases}$$\n\n**Step 3. 단계: 넓이 계산**\n\n넓이는 $x$축과 곡선 사이의 면적이므로:\n\n\n**∴ 답: $\\pi+2$**\n\n① $\\pi+1$: 배각 공식 적용 오류입니다\n② $\\pi+\\frac{3}{2}$: 부호를 잘못 적용한 결과입니다\n④ $\\pi+\\frac{5}{2}$: 항등식 선택 오류입니다\n⑤ $\\pi+3$: 배각 공식 적용 오류입니다\n\n**💡 포인트:** 배각 공식의 다양한 변형을 상황에 맞게 선택합니다.",
    "problem": "곡선 $y=|\\sin 2x|+1$과 $x$축 및 두 직선 $x=\\frac{\\pi}{4}, x=\\frac{5\\pi}{4}$로 둘러싼 부분의 넓이는? [3점]\n\n① $\\pi+1$\n\n② $\\pi+\\frac{3}{2}$\n\n③ $\\pi+2$\n\n④ $\\pi+\\frac{5}{2}$\n\n⑤ $\\pi+3$",
