    "answer": 1,
    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 매개변수 방정식에서 점 P의 위치는:\n$$x = 2t - \\cos t, \\quad y = 4 - \\sin t$$\n\n**Step 1. 단계: 속도 벡터 구하기**\n\n속도 벡터 $\\vec{v}$는 시간에 대한 미분:\n$$\\vec{v} = \\left(\\frac{dx}{dt}, \\frac{dy}{dt}\\right) = (\\sin t + 2, -\\cos t)$$\n\n시각 $t = \\alpha$에서의 속도 벡터:\n$$\\vec{v} = (\\sin \\alpha + 2, -\\cos \\alpha)$$\n\n**Step 2. 단계: 가속도 벡터 구하기**\n\n가속도 벡터 $\\vec{a}$는 속도의 미분:\n$$\\vec{a} = \\left(\\frac{d^2x}{dt^2}, \\frac{d^2y}{dt^2}\\right) = (\\cos t, \\sin t)$$\n\n시각 $t = \\alpha$에서의 가속도 벡터:\n$$\\vec{a} = (\\cos \\alpha, \\sin \\alpha)$$\n\n**Step 3. 단계: 내적 조건 적용**\n\n주어진 조건 $\\vec{v} \\cdot \\vec{a} = 1$:\n$$(\\sin \\alpha + 2, -\\cos \\alpha) \\cdot (\\cos \\alpha, \\sin \\alpha) = 1$$\n\n$$\\sin \\alpha \\cos \\alpha + 2\\cos \\alpha - \\cos \\alpha \\sin \\alpha = 1$$\n\n$$2\\cos \\alpha = 1$$\n\n$$\\cos \\alpha = \\frac{1}{2}$$\n\n**∴ 답: $\\frac{\\pi}{3}$**\n\n① $\\frac{\\pi}{6}$: 부호를 잘못 적용한 결과입니다\n③ $\\frac{\\pi}{2}$: 사분면 조건을 무시한 결과입니다\n④ $\\frac{2\\pi}{3}$: 분자·분모를 혼동한 결과입니다\n⑤ $\\frac{5\\pi}{6}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "좌표평면 위를 움직이는 점 P의 시각 $t(0<t<\\pi)$에서의 위치 P$(x, y)$가\n\n$$x=2t-\\cos t, \\quad y=4-\\sin t$$\n\n이다. 시각 $t=\\alpha(0<\\alpha<\\pi)$에서의 점 P의 속도 $\\vec{v}$와 가속도 $\\vec{a}$가 $\\vec{v} \\cdot \\vec{a}=1$을 만족시킬 때, $\\alpha$의 값은?\n\n① $\\frac{\\pi}{6}$\n\n② $\\frac{\\pi}{3}$\n\n③ $\\frac{\\pi}{2}$\n\n④ $\\frac{2\\pi}{3}$\n\n⑤ $\\frac{5\\pi}{6}$",
