    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각함수 변환 공식 $\\cos(\\pi+\\theta)=-\\cos\\theta$, $\\sin(\\pi-\\theta)=\\sin\\theta$, $\\cos(\\frac{\\pi}{2}+\\theta)=-\\sin\\theta$를 이용하여 식을 변환한 뒤, 피타고라스 항등식과 사분면 조건으로 값을 구합니다.\n\n주어진 조건: $f(x) = a\\cos(\\pi x^2)$이고 $\\lim_{x \\to 0} \\left\\{ \\frac{x^2+1}{x} \\int_1^{x+1} f(t) dt \\right\\} = 3$\n\n**Step 1. 적분 계산**\n\n$I(x) = \\int_1^{x+1} f(t) dt = \\int_1^{x+1} a\\cos(\\pi t^2) dt$\n\n$x \\to 0$일 때의 극한이므로, $x+1 \\to 1$입니다.\n\n**Step 2. 극한 분석**\n\n$\\lim_{x \\to 0} \\frac{x^2+1}{x} \\int_1^{x+1} f(t) dt = 3$\n\n$x \\to 0$일 때, $\\frac{x^2+1}{x} = \\frac{1}{x} + x \\to \\infty$이므로, 극한이 수렴하려면 $\\int_1^{x+1} f(t) dt \\sim \\frac{3x}{x^2+1}$의 형태여야 합니다.\n\n**Step 3. Taylor 전개**\n\n$x \\to 0$ 근처에서:\n$$\\int_1^{x+1} f(t) dt = \\int_1^{1+x} a\\cos(\\pi t^2) dt$$\n\n$t = 1 + u$ (단, $0 \\leq u \\leq x$)로 치환하면:\n$$\\int_0^x a\\cos(\\pi(1+u)^2) du = \\int_0^x a\\cos(\\pi(1 + 2u + u^2)) du$$\n\n$$= \\int_0^x a\\cos(\\pi + 2\\pi u + \\pi u^2) du = -\\int_0^x a\\cos(2\\pi u + \\pi u^2) du$$\n\n\n**∴ 답: 2**\n\n① 1: 부호를 잘못 적용한 결과입니다\n② $\\frac{3}{2}$: 항등식 대입 오류입니다\n④ $\\frac{5}{2}$: 분자·분모를 혼동한 결과입니다\n⑤ 3: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "함수 $f(x) = a\\cos(\\pi x^2)$에 대하여\n\n$$\\lim_{x \\to 0} \\left\\{ \\frac{x^2+1}{x} \\int_1^{x+1} f(t) dt \\right\\} = 3$$\n\n일 때, $f(a)$의 값은? (단, $a$는 상수이다.) [4점]\n\n① 1\n② $\\frac{3}{2}$\n③ 2\n④ $\\frac{5}{2}$\n⑤ 3",
