    "img": "2019_6월모의평가가형_23.png",
    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 조건: $\\cos\\theta = \\frac{1}{7}$일 때, $\\sec^2\\theta$의 값을 구하시오.\n\n**Step 1. sec θ의 정의**\n\n$$\\sec\\theta = \\frac{1}{\\cos\\theta}$$\n\n**Step 2. sec²θ 계산**\n\n$$\\sec^2\\theta = \\left(\\frac{1}{\\cos\\theta}\\right)^2 = \\frac{1}{\\cos^2\\theta}$$\n\n**Step 3. cos θ 값 대입**\n\n$\\cos\\theta = \\frac{1}{7}$이므로:\n\n$$\\cos^2\\theta = \\left(\\frac{1}{7}\\right)^2 = \\frac{1}{49}$$\n\n**Step 4. sec²θ 최종 계산**\n\n$$\\sec^2\\theta = \\frac{1}{\\cos^2\\theta} = \\frac{1}{\\frac{1}{49}} = 49$$\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: ③**\n\n**검산:** 구한 값을 원래 조건에 대입하여 등식이 성립하는지 확인합니다.\n\n\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$\\cos\\theta = \\frac{1}{7}$일 때, $\\sec^2\\theta$의 값을 구하시오. [3점]",
