    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 조건:\n- $f(x) = 3e^{5x} + x + \\sin x$\n- $g(x)$는 $f(x)$의 역함수\n- 곡선 $y = g(x)$는 점 $(3, 0)$을 지남\n- $\\lim_{x \\to 3} \\frac{x-3}{g(x)-g(3)}$의 값을 구하라\n\n**Step 1. 점 $(3, 0)$이 곡선 위의 점이라는 의미**\n\n곡선 $y = g(x)$가 점 $(3, 0)$을 지나므로:\n$$g(3) = 0$$\n\n**Step 2. $g$가 $f$의 역함수임을 이용**\n\n$g(x) = f^{-1}(x)$이므로:\n$$f(g(3)) = 3$$\n$$f(0) = 3$$\n\n검증: $f(0) = 3e^0 + 0 + \\sin 0 = 3 + 0 + 0 = 3$ ✓\n\n**Step 3. 극한값 계산**\n\n$$\\lim_{x \\to 3} \\frac{x-3}{g(x)-g(3)}$$\n\n$g(3) = 0$을 대입하면:\n$$\\lim_{x \\to 3} \\frac{x-3}{g(x)-0} = \\lim_{x \\to 3} \\frac{x-3}{g(x)}$$\n\n분자와 분모가 모두 0으로 수렴하므로 로피탈의 정리를 적용할 수 있습니다.\n\n역함수의 미분법을 이용하면:\n$$\\lim_{x \\to 3} \\frac{x-3}{g(x)-g(3)} = \\lim_{x \\to 3} \\frac{1}{\\frac{g(x)-g(3)}{x-3}} = \\frac{1}{g'(3)}$$\n\n**∴ 답: ③**\n\n**검산:** 구한 값을 원래 조건에 대입하여 등식이 성립하는지 확인합니다.\n\n\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "함수 $f(x)=3e^{5x}+x+\\sin x$의 역함수를 $g(x)$라 할 때, 곡선 $y=g(x)$는 점 $(3, 0)$을 지난다. $\\lim_{x \\to 3} \\frac{x-3}{g(x)-g(3)}$의 값을 구하시오. [3점]",
