    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** $y = A\\sin(Bx+C)+D$에서 최댓값=$|A|+D$, 최솟값=$-|A|+D$입니다.\n\n**Step 1. 점 P의 위치는 매개변수 방정식 $x = 3t - \\sin t$**\n점 P의 위치는 매개변수 방정식 $x = 3t - \\sin t$, $y = 4 - \\cos t$ (단, $t \\geq 0$)로 주어집니다.\n\n**Step 2. 속도 성분을 구하면**\n$$v_x = \\frac{dx}{dt} = 3 - \\cos t$$\n$$v_y = \\frac{dy}{dt} = \\sin t$$\n\n**Step 3. 속력(speed)은**\n$$v = \\sqrt{v_x^2 + v_y^2} = \\sqrt{(3-\\cos t)^2 + \\sin^2 t}$$\n\n**Step 4. 전개하면**\n$$v^2 = 9 - 6\\cos t + \\cos^2 t + \\sin^2 t$$\n$$= 9 - 6\\cos t + 1 = 10 - 6\\cos t$$\n\n\n\n**참고:** $y=A\\sin(Bx+C)+D$에서 진폭=$|A|$, 주기=$\\frac{2\\pi}{|B|}$, 최댓값=$D+|A|$, 최솟값=$D-|A|$. $\\cos$도 동일합니다.\n\n**∴ 답: 5**\n\n① 3: 진폭과 수직이동을 혼동한 결과입니다\n② 4: 주기 공식 적용 오류입니다\n④ 6: 위상이동을 무시한 결과입니다\n⑤ 7: 진폭과 수직이동을 혼동한 결과입니다\n\n**💡 포인트:** 표준형과 비교하여 진폭, 주기, 이동량을 정확히 파악합니다.",
    "problem": "좌표평면 위를 움직이는 점 P의 시각 $t(t \\geq 0)$에서의 위치 $(x, y)$가\n\n$$x = 3t - \\sin t, \\quad y = 4 - \\cos t$$\n\n이다. 점 P의 속력의 최댓값을 $M$, 최솟값을 $m$이라 할 때, $M + m$의 값은? [3점]\n\n① 3\n② 4\n③ 5\n④ 6\n⑤ 7",
