    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** $y = A\\sin(Bx+C)+D$에서 최댓값=$|A|+D$, 최솟값=$-|A|+D$입니다.\n\n주어진 함수를 정리하겠습니다.\n\n$$f(x) = \\cos^2\\left(x - \\frac{3}{4}\\pi\\right) - \\cos\\left(x - \\frac{\\pi}{4}\\right) + k$$\n\n**Step 1. $\\cos^2\\left(x - \\frac{3}{4}\\pi\\rig**\n\n배각공식 $\\cos^2\\theta = \\frac{1 + \\cos 2\\theta}{2}$를 이용하면:\n\n$$\\cos^2\\left(x - \\frac{3}{4}\\pi\\right) = \\frac{1 + \\cos\\left(2x - \\frac{3}{2}\\pi\\right)}{2}$$\n\n$\\cos\\left(2x - \\frac{3}{2}\\pi\\right) = \\cos\\left(2x - \\frac{3}{2}\\pi\\right) = -\\sin(2x)$ 이므로:\n\n$$\\cos^2\\left(x - \\frac{3}{4}\\pi\\right) = \\frac{1 - \\sin(2x)}{2}$$\n\n**Step 2. 함수를 $t$로 치환**\n\n$t = \\cos\\left(x - \\frac{\\pi}{4}\\right)$로 놓으면, $t \\in [-1, 1]$입니다.\n\n$\\sin(2x)$를 $t$로 표현하면:\n\n$$\\sin(2x) = \\sin\\left(2\\left(x - \\frac{\\pi}{4}\\right) + \\frac{\\pi}{2}\\right) = \\cos\\left(2\\left(x - \\frac{\\pi}{4}\\right)\\right) = 2\\cos^2\\left(x - \\frac{\\pi}\n\n**∴ 답: $\\frac{5}{2}$**\n\n① 2: 진폭과 수직이동을 혼동한 결과입니다\n② $\\frac{9}{4}$: 주기 공식 적용 오류입니다\n④ $\\frac{11}{4}$: 위상이동을 무시한 결과입니다\n⑤ 3: 진폭과 수직이동을 혼동한 결과입니다\n\n**💡 포인트:** 표준형과 비교하여 진폭, 주기, 이동량을 정확히 파악합니다.",
    "problem": "실수 $k$에 대하여 함수\n\n$$f(x) = \\cos^2\\left(x - \\frac{3}{4}\\pi\\right) - \\cos\\left(x - \\frac{\\pi}{4}\\right) + k$$\n\n의 최댓값은 3, 최솟값은 $m$이다. $k+m$의 값은? [4점]\n\n① 2\n② $\\frac{9}{4}$\n③ $\\frac{5}{2}$\n④ $\\frac{11}{4}$\n⑤ 3",
