    "answer": 1,
    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 적분을 계산합니다.\n\n$$\\int_{0}^{\\pi/2} (\\cos x + 3\\cos^3 x)dx$$\n\n**Step 1. 각 항을 분리하여 적분**\n\n$$\\int_{0}^{\\pi/2} \\cos x dx + \\int_{0}^{\\pi/2} 3\\cos^3 x dx$$\n\n**Step 2. 첫 번째 항 계산**\n\n$$\\int_{0}^{\\pi/2} \\cos x dx = [\\sin x]_{0}^{\\pi/2} = 1 - 0 = 1$$\n\n**Step 3. 두 번째 항 계산 ($\\cos^3 x$ 적분)**\n\n$\\cos^3 x$를 적분하기 위해 다음 공식을 사용합니다:\n\n$$\\cos^3 x = \\cos x (1 - \\sin^2 x)$$\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: ②**\n\n\n\n**참고:** 수능에서 이 유형은 빈출 문제이므로, 기본 공식을 정확히 암기하고 부호 결정 과정을 반복 연습하는 것이 중요합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$\\int_{0}^{\\frac{\\pi}{2}} (\\cos x + 3\\cos^3 x)dx$의 값을 구하시오. [3점]",
