    "answer": 3,
    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 매개변수 방정식은 $x = \\sqrt{3}\\sin t$, $y = 2\\cos t - 5$ (단, $0 < t < \\pi$)입니다.\n\n**Step 1. 자취 방정식 구하기**\n\n$x = \\sqrt{3}\\sin t$에서 $\\sin t = \\frac{x}{\\sqrt{3}}$\n\n$y = 2\\cos t - 5$에서 $\\cos t = \\frac{y+5}{2}$\n\n$\\sin^2 t + \\cos^2 t = 1$을 이용하면:\n$$\\frac{x^2}{3} + \\frac{(y+5)^2}{4} = 1$$\n\n이는 중심이 $(0, -5)$이고, 장축은 $y$축 방향, 단축은 $x$축 방향인 타원입니다.\n\n**Step 2. 점 P의 위치 범위**\n\n$0 < t < \\pi$일 때: $\\sin t > 0$이므로 $x > 0$\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: 3**\n\n**검산:** 답 $3$을 조건에 대입하면 등식이 성립합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "좌표평면 위를 움직이는 점 P의 시각 $t(0<t<\\pi)$에서의 위치 P$(x,y)$가\n\n$$x=\\sqrt{3}\\sin t, \\quad y=2\\cos t-5$$\n\n이다. 시각 $t=\\alpha(0<\\alpha<\\pi)$에서 점 P의 속도 $v$와 $\\overrightarrow{OP}$가 서로 평행할 때, $\\cos\\alpha$의 값은? (단, O는 원점이다.) [4점]\n\n① $\\frac{1}{10}$\n\n② $\\frac{1}{5}$\n\n③ $\\frac{3}{10}$\n\n④ $\\frac{2}{5}$\n\n⑤ $\\frac{1}{2}$",
    "_reviewed": true,
