    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n**Step 1. sin(7π/3)을 구하기 위해 먼저 각을 단순화합니다.**\nsin(7π/3)을 구하기 위해 먼저 각을 단순화합니다.\n\n**Step 2. 7π/3 = 6π/3 + π/3 = 2π + π/3**\n7π/3 = 6π/3 + π/3 = 2π + π/3\n\n**Step 3. 삼각함수의 주기성에 의해**\nsin(2π + π/3) = sin(π/3)\n\n**Step 4. sin(π/3) = √3/2 이지만, 이는 선택지에 있습니다.**\nsin(π/3) = √3/2 이지만, 이는 선택지에 있습니다.\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: ②**\n\n① $-\\frac{\\sqrt{2}}{2}$ ② $-\\frac{1}{2}$ ③ $\\frac{1}{2}$ ④ $\\frac{\\sqrt{2}}{2}$ ⑤ $\\frac{\\sqrt{3}}{2}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
