    "explanation": "**[풀이]**\n\n**기본 개념:** 배각 공식 $\\sin 2\\theta = 2\\sin\\theta\\cos\\theta$, $\\cos 2\\theta = 1 - 2\\sin^2\\theta$를 이용합니다.\n\n점 P는 시각 $t=0$일 때 $(0, -1)$에서 출발하여 속도 $\\vec{v} = (2t, 2\\pi\\sin 2\\pi t)$로 움직입니다.\n\n**Step 1. 단계: 점 P의 위치 구하기**\n\n$x(t) = \\int_0^t 2s \\, ds = t^2$\n\n$y(t) = -1 + \\int_0^t 2\\pi\\sin 2\\pi s \\, ds = -1 + 2\\pi \\cdot \\left[-\\frac{\\cos 2\\pi s}{2\\pi}\\right]_0^t$\n\n$= -1 - \\cos 2\\pi t + 1 = -\\cos 2\\pi t$\n\n\n\n**참고:** 배각 공식: $\\sin 2\\theta=2\\sin\\theta\\cos\\theta$, $\\cos 2\\theta=1-2\\sin^2\\theta=2\\cos^2\\theta-1$입니다.\n\n\n\n\n\n**보충 설명:** $\\cos 2\\theta$에는 세 가지 표현이 있습니다: $\\cos^2\\theta - \\sin^2\\theta$, $2\\cos^2\\theta - 1$, $1 - 2\\sin^2\\theta$. 주어진 조건에 따라 가장 효율적인 형태를 선택하는 것이 핵심입니다.\n\n**∴ 답: 2**\n\n**검산:** 답 $2$을 조건에 대입하면 등식이 성립합니다.\n\n\n\n**💡 포인트:** 배각 공식의 다양한 변형을 상황에 맞게 선택합니다.",
    "problem": "좌표평면에서 점 P는 시각 $t=0$일 때 $(0, -1)$에서 출발하여 시각 $t$에서의 속도가\n\n$$\\vec{v} = (2t, 2\\pi \\sin 2\\pi t)$$\n\n이고, 점 Q는 시각 $t=0$일 때 출발하여 시각 $t$에서의 위치가\n\n$$Q(4\\sin 2\\pi t, |\\cos 2\\pi t|)$$\n\n이다. 출발한 후 두 점 P, Q가 만나는 횟수는? [4점]\n\n① 1\n② 2\n③ 3\n④ 4\n⑤ 5",
