    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n**Step 1. 주어진 조건**\n- $F(x) = \\ln|f(x)|$에서 $F'(x) = \\frac{f'(x)}{f(x)}$\n- $G(x) = \\ln|g(x)\\sin x|$에서 $G'(x) = \\frac{g'(x)}{g(x)} + \\cot x$\n\n**Step 2. 조건 1: $\\lim_{x \\to 1}(x-1)F'(x) = 3**\n**조건 1: $\\lim_{x \\to 1}(x-1)F'(x) = 3$**\n\n**Step 3. $F'(x) = \\frac{f'(x)}{f(x)}$이므로, 극한**\n$F'(x) = \\frac{f'(x)}{f(x)}$이므로, 극한이 유한한 값 3이 되려면 $f(1) = 0$이어야 합니다.\n\n**Step 4. $f(x) = (x-1)h(x)$로 놓으면 ($h(1) \\neq**\n$$F'(x) = \\frac{h(x) + (x-1)h'(x)}{(x-1)h(x)}$$\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: 53**\n\n**검산:** 답 $53$을 조건에 대입하면 등식이 성립합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "최고차항의 계수가 1인 사차함수 $f(x)$에 대하여\n\n$$F(x) = \\ln|f(x)|$$\n\n라 하고, 최고차항의 계수가 1인 삼차함수 $g(x)$에 대하여\n\n$$G(x) = \\ln|g(x)\\sin x|$$\n\n라 하자.\n\n$$\\lim_{x \\to 1}(x-1)F'(x) = 3, \\quad \\lim_{x \\to 0}\\frac{F'(x)}{G'(x)} = \\frac{1}{4}$$\n\n일 때, $f(3) + g(3)$의 값은? [4점]\n\n① 57\n② 55\n③ 53\n④ 51\n⑤ 49",
