    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 함수: $f(x) = -\\cos^2 x$\n\n**Step 1. 도함수 구하기**\n\n$f'(x) = -\\frac{d}{dx}(\\cos^2 x)$\n\n연쇄법칙을 사용하면:\n\n$f'(x) = -2\\cos x \\cdot (-\\sin x) = 2\\sin x \\cos x$\n\n삼각함수 항등식 $2\\sin x \\cos x = \\sin 2x$를 적용하면:\n\n$f'(x) = \\sin 2x$\n\n**Step 2. $f'\\left(\\frac{\\pi}{4}\\right)$ 계산하기**\n\n$f'\\left(\\frac{\\pi}{4}\\right) = \\sin\\left(2 \\cdot \\frac{\\pi}{4}\\right)$\n\n$= \\sin\\left(\\frac{\\pi}{2}\\right)$\n\n$= 1$\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n**∴ 답: ③**\n\n**검산:** 구한 값을 원래 조건에 대입하여 등식이 성립하는지 확인합니다.\n\n\n\n**참고:** 수능에서 이 유형은 빈출 문제이므로, 기본 공식을 정확히 암기하고 부호 결정 과정을 반복 연습하는 것이 중요합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
