    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 적분을 계산합니다.\n\n$$\\int_{0}^{\\frac{\\pi}{2}} 2\\sin x \\, dx$$\n\n**Step 1. 부정적분 구하기**\n\n$\\sin x$의 부정적분은 $-\\cos x$이므로:\n\n$$\\int 2\\sin x \\, dx = -2\\cos x + C$$\n\n**Step 2. 정적분 계산**\n\n정적분의 기본정리를 적용합니다:\n\n$$\\int_{0}^{\\frac{\\pi}{2}} 2\\sin x \\, dx = \\left[-2\\cos x\\right]_{0}^{\\frac{\\pi}{2}}$$\n\n**Step 3. 상한과 하한 대입**\n\n$$= -2\\cos\\left(\\frac{\\pi}{2}\\right) - \\left(-2\\cos 0\\right)$$\n\n$$= -2 \\cdot 0 - (-2 \\cdot 1)$$\n\n$$= 0 + 2$$\n\n$$= 2$$\n\n**∴ 답: 1**\n\n① 0: 부호를 잘못 적용한 결과입니다\n② $\\frac{1}{2}$: 항등식 대입 오류입니다\n④ $\\frac{3}{2}$: 분자·분모를 혼동한 결과입니다\n⑤ 2: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
