    "answer": 4,
    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 함수: $f(x) = e^{-x} \\int_0^x \\sin(t^2) dt$\n\n**Step 1. 도함수 구하기**\n\n곱의 미분법을 사용하면:\n$$f'(x) = -e^{-x} \\int_0^x \\sin(t^2) dt + e^{-x} \\sin(x^2)$$\n$$f'(x) = e^{-x}\\left[\\sin(x^2) - \\int_0^x \\sin(t^2) dt\\right]$$\n\n**Step 2. 각 선택지 검토**\n\n**ㄱ. $f(\\sqrt{\\pi}) > 0$ 검토**\n\n$0 < x < \\sqrt{\\pi}$에서 $\\sin(t^2) > 0$이므로 $\\int_0^{\\sqrt{\\pi}} \\sin(t^2) dt > 0$\n\n$e^{-\\sqrt{\\pi}} > 0$이므로:\n$$f(\\sqrt{\\pi}) = e^{-\\sqrt{\\pi}} \\int_0^{\\sqrt{\\pi}} \\sin(t^2) dt > 0$$\n\n**ㄱ은 참** ✓\n\n**ㄴ. $f'(a) > 0$을 만족하는 $a \\in (0, \\sqrt{\\pi})$ 존재 검토**\n\n$f'(x) > 0 \\Leftrightarrow \\sin(x^2) > \\int_0^x \\sin(t^2) dt$\n\n$x = 0$ 근처에서: 테일러 전개 $\\sin(t^2) \\approx t^2 - \\frac{t^6}{6} + ...$\n\n$$\\int_0^x \\sin(t^2) dt \\approx \\frac{x^3}{3} - \\frac{x^7}{42} + ...$$\n\n\n**∴ 답: 4**\n\n**검산:** 답 $4$을 조건에 대입하면 등식이 성립합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "함수 $f(x) = e^{-x} \\int_{0}^{x} \\sin(t^2) dt$에 대하여 <보기>에서 옳은 것을 모두 고른 것은? [4점]\n\n<보 기>\nㄱ. $f(\\sqrt{\\pi}) > 0$\n\nㄴ. $f'(a) > 0$을 만족시키는 $a$가 열린 구간 $(0, \\sqrt{\\pi})$에 적어도 하나 존재한다.\n\nㄷ. $f'(b) = 0$을 만족시키는 $b$가 열린 구간 $(0, \\sqrt{\\pi})$에 적어도 하나 존재한다.\n\n① ㄱ　② ㄷ　③ ㄱ, ㄴ　④ ㄴ, ㄷ　⑤ ㄱ, ㄴ, ㄷ",
