    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n**Step 1. 조건 (가)에서 $f(x)$의 형태 파악**\n\n$f(x) = f(-x)$이므로 $f(x)$는 우함수(짝함수)입니다.\n\n\n\n**참고:** 사분면별 부호 — 1사분면: 모두(+), 2사분면: $\\sin(+)\\cos(-)$, 3사분면: 모두(-), 4사분면: $\\sin(-)\\cos(+)$. $\\tan$은 $\\sin/\\cos$의 부호로 결정됩니다.\n\n\n\n\n\n**보충 설명:** 삼각함수의 값을 구할 때 가장 흔한 실수는 사분면 조건을 무시하는 것입니다. 제곱근을 취하면 $\\pm$가 나오므로, 각이 속한 사분면에서의 부호를 반드시 확인해야 합니다. 제1사분면은 모두 양수, 제2사분면은 $\\sin>0, \\cos<0$, 제3사분면은 모두 음수, 제4사분면은 $\\sin<0, \\cos>0$입니다.\n\n\n\n**보충 설명:** 삼각함수 값을 구할 때 가장 흔한 실수는 사분면 조건을 무시하는 것입니다. 제곱근을 취하면 $\\pm$가 나오므로, 각이 속한 사분면의 부호를 반드시 확인합니다. 제1사분면: 모두(+), 제2사분면: $\\sin(+), \\cos(-)$, 제3사분면: 모두(-), 제4사분면: $\\sin(-), \\cos(+)$입니다.\n\n**∴ 답: 5**\n\n**검산:** 답 $5$을 조건에 대입하면 등식이 성립합니다.\n\n\n\n수능 빈출 유형으로 기본 공식 암기와 반복 연습이 중요합니다.\n\n**💡 포인트:** 수능 빈출 유형으로, 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "실수 전체의 집합에서 미분가능한 함수 $f(x)$가 상수 $a(0 < a < 2\\pi)$와 모든 실수 $x$에 대하여 다음 조건을 만족시킨다.\n\n(가) $f(x) = f(-x)$\n\n(나) $\\int_x^{x+a} f(t)dt = \\sin\\left(x + \\frac{\\pi}{3}\\right)$\n\n단힌 구간 $\\left[0, \\frac{a}{2}\\right]$에서 두 실수 $b, c$에 대하여\n\n$$f(x) = b\\cos(3x) + c\\cos(5x)$$\n\n일 때 $abc = -\\frac{q}{p}\\pi$이다.\n\n$p+q$의 값을 구하시오. (단, $p$와 $q$는 서로소인 자연수이다.)",
