    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n**Step 1. 주어진 조건**\n- $\\cos(\\alpha + \\beta) = \\frac{5}{7}$\n- $\\cos\\alpha\\cos\\beta = \\frac{4}{7}$\n- $\\sin\\alpha\\sin\\beta$의 값을 구하기\n\n**Step 2. 코사인 덧셈 공식 이용**\n$$\\cos(\\alpha + \\beta) = \\cos\\alpha\\cos\\beta - \\sin\\alpha\\sin\\beta$$\n\n**Step 3. 주어진 값을 대입**\n$$\\frac{5}{7} = \\frac{4}{7} - \\sin\\alpha\\sin\\beta$$\n\n**Step 4. $\\sin\\alpha\\sin\\beta$에 대해 정리**\n$$\\sin\\alpha\\sin\\beta = \\frac{4}{7} - \\frac{5}{7}$$\n\n**∴ 답: $-\\frac{4}{7}$**\n\n① $-\\frac{1}{7}$: 부호를 잘못 적용한 결과입니다\n② $-\\frac{2}{7}$: 항등식 대입 오류입니다\n③ $-\\frac{3}{7}$: 사분면 조건을 무시한 결과입니다\n⑤ $-\\frac{5}{7}$: 부호를 잘못 적용한 결과입니다\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "$\\cos(a+\\beta) = \\frac{5}{7}$, $\\cos a \\cos \\beta = \\frac{4}{7}$일 때, $\\sin a \\sin \\beta$의 값은?\n\n① $-\\frac{1}{7}$\n\n② $-\\frac{2}{7}$\n\n③ $-\\frac{3}{7}$\n\n④ $-\\frac{4}{7}$\n\n⑤ $-\\frac{5}{7}$",
