    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용하여 삼각함수 값을 구합니다. 사분면에 따라 부호가 결정됩니다.\n\n주어진 조건을 정리하면:\n- $g(x) = |2\\sin(x+2|x|)+1|$\n- $h(x) = f(g(x))$는 실수 전체에서 미분가능\n- $h'(x)$는 실수 전체에서 연속이고 미분가능\n- $f'(3)$의 값을 구해야 함\n\n**Step 1. $g(x)$의 성질 파악**\n\n$x \\geq 0$일 때: $g(x) = |2\\sin(3x)+1|$\n\n$x < 0$일 때: $g(x) = |2\\sin(-x)+1|$\n\n$g(x)$는 우함수도 기함수도 아니므로 자세히 분석해야 함.\n\n**Step 2. $h(x)$가 미분가능한 조건**\n\n$h'(x) = f'(g(x)) \\cdot g'(x)$\n\n$h'(x)$가 실수 전체에서 연속이려면, $g'(x)$가 불연속인 점에서 $f'(g(x)) = 0$이어야 함.\n\n$g(x)$는 $x = 0$에서 미분불가능할 수 있음.\n\n**Step 3. $x = 0$ 근처에서 $g(x)$ 분석**\n\n$x \\to 0^+$: $g(x) = |2\\sin(3x)+1| \\approx |1+6x| = 1+6x$ (작은 $x > 0$)\n\n$x \\to 0^-$: $g(x) = |2\\sin(-x)+1| \\approx |1-2x| = 1-2x$ (작은 $|x|$, $x < 0$)\n\n**∴ 답: 2**\n\n**검산:** 답 $2$을 조건에 대입하면 등식이 성립합니다.\n\n**💡 포인트:** 항등식으로 크기를 구한 뒤 사분면 조건으로 부호를 결정하는 것이 핵심입니다.",
    "problem": "최고차항의 계수가 1인 사차함수 $f(x)$와 함수\n$$g(x) = |2\\sin(x+2|x|)+1|$$\n에 대하여 함수 $h(x) = f(g(x))$는 실수 전체의 집합에서 이계도함수 $h''(x)$를 갖고, $h''(x)$는 실수 전체의 집합에서 연속이다. $f'(3)$의 값을 구하시오. [4점]",
