    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각함수의 덧셈 공식은 두 각의 합(또는 차)에 대한 삼각함수 값을 구할 때 사용합니다. 사인의 덧셈 공식은 다음과 같습니다.\n$$\\sin(A + B) = \\sin A \\cos B + \\cos A \\sin B$$\n이 공식은 단위원 위의 두 점 사이의 거리를 이용해 증명할 수 있으며, 수능에서 가장 기본적으로 출제되는 공식입니다.\n\n**Step 1. 덧셈 공식 세우기**\n$\\sin(30° + 60°)$에 사인 덧셈 공식을 적용합니다.\n$$\\sin(30° + 60°) = \\sin 30° \\cos 60° + \\cos 30° \\sin 60°$$\n\n**Step 2. 특수각의 값 대입 및 계산**\n각각의 삼각함수 값을 대입합니다.\n$$= \\frac{1}{2} \\times \\frac{1}{2} + \\frac{\\sqrt{3}}{2} \\times \\frac{\\sqrt{3}}{2} = \\frac{1}{4} + \\frac{3}{4} = \\frac{4}{4} = 1$$\n\n**Step 3. 검증**\n$30° + 60° = 90°$이므로 $\\sin 90° = 1$과 일치하여 계산이 정확합니다.\n\n**∴ 답: ⑤**\n\n① $\\frac{1}{2}$: $\\sin 30°$의 값만 택하여 덧셈 공식을 적용하지 않은 실수입니다.\n② $\\frac{\\sqrt{3}}{2}$: $\\sin 60°$의 값만 택한 경우입니다. 덧셈 공식의 두 항을 모두 구해 합산해야 합니다.\n③ $\\frac{1}{4}$: 첫 번째 항 $\\sin 30° \\cos 60° = \\frac{1}{4}$만 계산하고 두 번째 항을 빠뜨린 경우입니다.\n④ $\\frac{\\sqrt{3}}{4}$: 근호를 포함한 계산 실수로, 계산 과정을 처음부터 다시 확인해야 합니다.\n\n**💡 포인트:** 덧셈 공식 $\\sin(A+B) = \\sin A \\cos B + \\cos A \\sin B$의 두 항을 **모두** 계산하여 더하는 것이 중요합니다. $\\sin 90° = 1$이라는 기본값으로 검증할 수 있습니다.",
