    "explanation": "**[풀이]**\n\n**기본 개념:** 삼각함수의 덧셈 공식 $\\sin(\\alpha + \\beta) = \\sin\\alpha\\cos\\beta + \\cos\\alpha\\sin\\beta$를 사용합니다. 주어진 삼각함수값으로부터 나머지 값을 구하기 위해 피타고라스 항등식 $\\sin^2\\theta + \\cos^2\\theta = 1$을 이용합니다. 예각(제1사분면)에서는 모든 삼각함수값이 양수입니다.\n\n**Step 1. $\\cos\\alpha$ 구하기**\n$\\sin\\alpha = \\frac{3}{5}$이고 $\\alpha$가 예각이므로 $\\cos\\alpha > 0$입니다.\n$$\\cos^2\\alpha = 1 - \\sin^2\\alpha = 1 - \\frac{9}{25} = \\frac{16}{25} \\implies \\cos\\alpha = \\frac{4}{5}$$\n\n**Step 2. $\\sin\\beta$ 구하기**\n$\\cos\\beta = \\frac{5}{13}$이고 $\\beta$가 예각이므로 $\\sin\\beta > 0$입니다.\n$$\\sin^2\\beta = 1 - \\cos^2\\beta = 1 - \\frac{25}{169} = \\frac{144}{169} \\implies \\sin\\beta = \\frac{12}{13}$$\n\n**Step 3. 덧셈 공식 적용**\n$$\\sin(\\alpha + \\beta) = \\frac{3}{5} \\cdot \\frac{5}{13} + \\frac{4}{5} \\cdot \\frac{12}{13} = \\frac{15}{65} + \\frac{48}{65} = \\frac{63}{65}$$\n\n**∴ 답: ①**\n\n② $\\frac{63}{65}$: 피타고라스 정리에서 $\\cos\\alpha$ 또는 $\\sin\\beta$를 잘못 구하여 틀린 결과입니다.\n③ $\\frac{48}{65}$: 뺄셈 공식 $\\sin(\\alpha-\\beta)$를 잘못 적용하거나 부호 처리가 잘못된 결과입니다.\n④ $\\frac{33}{65}$: 분모를 통분하는 과정에서 분자 계산 오류가 발생한 결과입니다.\n⑤ $\\frac{72}{65}$: 덧셈 공식의 두 번째 항 $\\cos\\alpha\\sin\\beta$를 빠뜨린 불완전한 계산 결과입니다.\n\n**💡 포인트:** 예각 조건에서 피타고라스 정리로 나머지 삼각함수값을 구할 때 반드시 양수를 선택합니다. 덧셈 공식의 두 항을 **모두 더해야** 완전한 답이 됩니다.",
