    "explanation": "**[풀이]**\n\n**기본 개념:** 코사인법칙으로 변의 길이를 구한 후, 사인법칙으로 외접원의 반지름을 구하는 복합 문제입니다.\n- **코사인법칙**: $a^2 = b^2 + c^2 - 2bc\\cos A$\n- **사인법칙**: $\\frac{a}{\\sin A} = 2R$\n- $\\cos A$가 주어지면 $\\sin A = \\sqrt{1-\\cos^2 A}$으로 구합니다. (삼각형 내각이므로 $\\sin A > 0$)\n\n**Step 1. 코사인법칙으로 변의 길이 구하기**\n$\\cos A$와 두 변 $b$, $c$를 코사인법칙에 대입합니다.\n$$a^2 = b^2 + c^2 - 2bc\\cos A$$\n\n**Step 2. $\\sin A$ 구하기**\n$$\\sin^2 A = 1 - \\cos^2 A$$\n삼각형의 내각이므로 $\\sin A > 0$만 취합니다.\n\n**Step 3. 사인법칙으로 $R$ 구하기**\n$$2R = \\frac{a}{\\sin A} \\implies R = \\frac{a}{2\\sin A}$$\n\n**∴ 답: ②**\n\n① $R = \\frac{5}{2}$: 코사인법칙과 사인법칙의 적용 순서를 잘못하여 중간 계산이 틀린 경우입니다.\n③ $R = 3$: $\\frac{a}{\\sin A} = 2R$ 에서 값 대입을 잘못한 경우입니다.\n④ $R = \\frac{7}{2}$: 코사인법칙에서 변의 길이를 잘못 계산하여 이후 계산이 연쇄적으로 틀린 경우입니다.\n⑤ $R = 4$: 조건을 연립하는 과정에서 대입 오류 또는 약분 실수가 발생한 경우입니다.\n\n**💡 포인트:** 코사인법칙 → $\\sin A$ 구하기 → 사인법칙의 **3단계 순서**로 풀어야 합니다. $\\cos A$에서 $\\sin A$를 구할 때 삼각형 내각은 항상 $\\sin > 0$임을 기억하세요.",
