    "problem": "예각 $\\alpha, \\beta$에 대하여 $\\sin\\alpha = \\frac{3}{5}$, $\\cos\\beta = \\frac{5}{13}$이고, $\\tan(\\alpha+\\beta) = -\\frac{56}{33}$일 때, $\\sin(\\alpha+2\\beta)$의 값은?\n\n(단, $\\alpha + \\beta$는 둔각)",
