    "problem": "함수 $f(x) = 3\\sin x + 4\\cos x$에 대하여 다음 조건들을 만족한다.\n\n(가) $f(x) = R\\sin(x+\\alpha)$ 형태로 나타낼 때, $R > 0$, $0 < \\alpha < \\frac{\\pi}{2}$\n\n(나) $g(x) = f(x) + f(x+\\frac{\\pi}{6})$일 때, $g(x)$의 최댓값이 $m$\n\n$m$의 값을 구하시오.",
