    "problem": "양수 $\\alpha$가 다음 조건을 만족한다.\n\n(가) $\\sin 2\\alpha + \\cos 2\\alpha = \\frac{7}{5}$\n\n(나) $0 < \\alpha < \\frac{\\pi}{2}$\n\n$\\tan \\alpha = \\frac{p}{q}$일 때, $p + q$의 최솟값을 구하시오. (단, $p, q$는 양의 정수, $\\gcd(p,q)=1$)",
